import type { BBox, GrainKind, LayerName, Line, Material, PenName, PenSpec, Pt, StrokeOpts, StrokeResult, Tier } from '@/lib/ink/types'
import { BLEND, esc, n, paint, type PaintKey } from '@/lib/ink/paint'
import { hashSeed, makeRng, type Rng } from '@/lib/ink/rng'
import { TIERS, smoothClosed } from '@/lib/ink/geom'
import { dot as penDot, stroke as penStroke } from '@/lib/ink/pen'
import { pen as resolvePen } from '@/lib/ink/pens'

export const GRAINS: readonly GrainKind[] = ['felt', 'marker', 'graphite', 'waxy', 'stamp']

export const MASK_VARIANTS = 6

export function maskId(grain: GrainKind, variant: number): string {
  return `ll-${grain}-${((variant % MASK_VARIANTS) + MASK_VARIANTS) % MASK_VARIANTS}`
}

export const MASK_IDS: readonly string[] = GRAINS.flatMap((g) => Array.from({ length: MASK_VARIANTS }, (_, v) => maskId(g, v)))

export function maskPhase(variant: number): { x: number; y: number; rot: 0 | 90 | 180 | 270 } {
  const v = ((variant % MASK_VARIANTS) + MASK_VARIANTS) % MASK_VARIANTS
  const rots = [0, 90, 180, 270, 0, 180] as const
  return { x: (v * 0.618034) % 1, y: (v * 0.381966 + 0.17) % 1, rot: rots[v] }
}

export interface Knobs {
  wobble: number
  misreg: number
  bleed: number
  width: number
}

export interface InkOptions {
  tier?: Tier
  grain?: boolean
  calm?: boolean
  knobs?: Partial<Knobs>
}

export interface GroupAttrs {
  transform?: string
  clip?: string
  opacity?: number
  id?: string
  part?: string
  vars?: Record<string, number>
  hideOn?: string
  mask?: string
}

export interface InkResult {
  svg: string
  w: number
  h: number
  pad: number
  layers: LayerName[]
  parts: Partial<Record<LayerName, string>>
  bbox: BBox
}

interface PathItem {
  d: string
  fill: PaintKey
  op: number
  rule?: 'evenodd'
  stroke?: PaintKey
  sw?: number
  clip?: string
}
type Item = PathItem | { raw: string } | { scope: Scope }

class Scope {
  buckets: Partial<Record<Material, Item[]>> = {}
  readonly attrs?: GroupAttrs
  constructor(attrs?: GroupAttrs) {
    this.attrs = attrs
  }
  add(mat: Material, item: Item): void {
    ;(this.buckets[mat] ??= []).push(item)
  }
}

const ORDER: readonly Material[] = ['under', 'wash', 'hl', 'marker', 'pencil', 'waxy', 'text', 'felt', 'stamp', 'top']
const GRAIN_OF: Partial<Record<Material, GrainKind>> = { marker: 'marker', pencil: 'graphite', waxy: 'waxy', text: 'felt', felt: 'felt', stamp: 'stamp' }
const BLENDED: ReadonlySet<Material> = new Set(['hl', 'marker'])
const SUBTLE: ReadonlySet<GrainKind> = new Set(['marker', 'felt'])

type Piece =
  | { t: 'raw'; s: string }
  | { t: 'mat'; grain?: GrainKind; blend: boolean; kids: Piece[] }
  | { t: 'grp'; pre: string; open: string; kids: Piece[]; plain: boolean }

const mergeOpts = (a: StrokeOpts | undefined, b: StrokeOpts | undefined): StrokeOpts => {
  if (!a) return b ?? {}
  if (!b) return a
  return { ...a, ...b, width: (a.width ?? 1) * (b.width ?? 1), alpha: (a.alpha ?? 1) * (b.alpha ?? 1) }
}

export class Ink {
  readonly rng: Rng
  readonly seed: number
  readonly tier: Tier
  readonly grain: boolean
  readonly calm: boolean
  readonly knobs: Knobs
  readonly variant: number
  private readonly tag: string
  private count = 0
  private defCount = 0
  private readonly roots = new Map<LayerName, Scope>()
  private leaned = false
  private cur: Scope
  private bb: BBox = [Infinity, Infinity, -Infinity, -Infinity]

  constructor(seed: string | number, opts: InkOptions = {}) {
    this.rng = makeRng(seed)
    this.seed = this.rng.seed
    this.calm = opts.calm ?? false
    this.tier = this.calm ? 'lo' : (opts.tier ?? 'lo')
    this.grain = opts.grain ?? true
    this.knobs = { wobble: 1, misreg: 1, bleed: 1, width: 1, ...opts.knobs }
    if (this.calm) {
      this.knobs.wobble *= 0.3
      this.knobs.misreg = 0
      this.knobs.width *= 0.85
    }
    this.variant = this.seed % MASK_VARIANTS
    this.tag = this.seed.toString(36)
    this.cur = this.rootOf('rest')
  }

  lean(): void {
    this.leaned = true
  }

  private rootOf(name: LayerName): Scope {
    let s = this.roots.get(name)
    if (!s) this.roots.set(name, (s = new Scope()))
    return s
  }

  next(name: string): Rng {
    return this.rng.fork(`${name}:${this.count++}`)
  }

  grow(bb: BBox): void {
    const b = this.bb
    if (bb[0] < b[0]) b[0] = bb[0]
    if (bb[1] < b[1]) b[1] = bb[1]
    if (bb[2] > b[2]) b[2] = bb[2]
    if (bb[3] > b[3]) b[3] = bb[3]
  }

  layer(name: LayerName, fn: () => void): void {
    const prev = this.cur
    this.cur = this.rootOf(name)
    try {
      fn()
    } finally {
      this.cur = prev
    }
  }

  group(attrs: GroupAttrs, fn: () => void, at: Material = 'top'): void {
    const scope = new Scope(attrs)
    this.cur.add(at, { scope })
    const prev = this.cur
    this.cur = scope
    try {
      fn()
    } finally {
      this.cur = prev
    }
  }

  part(name: string, fn: () => { dx: number; dy: number } | void, at: Material = 'wash'): void {
    const attrs: GroupAttrs = { part: name }
    this.group(attrs, () => {
      const off = fn()
      if (off) attrs.vars = { mx: off.dx, my: off.dy }
    }, at)
  }

  clipDef(d: string): string {
    const id = `ll-c${hashSeed(d).toString(36)}`
    this.cur.add('under', { raw: `<clipPath id="${id}"><path d="${d}"/></clipPath>` })
    return id
  }

  define(fn: () => void): string {
    const id = `ll-${this.tag}-${this.defCount++}`
    const scope = new Scope()
    const prev = this.cur
    this.cur = scope
    try {
      fn()
    } finally {
      this.cur = prev
    }
    this.cur.add('under', { raw: `<defs><g id="${id}">${this.emitScope(scope)}</g></defs>` })
    return id
  }

  use(id: string, o: { x?: number; y?: number; transform?: string } = {}, at: Material = 'top'): void {
    const xy = (o.x ? ` x="${n(o.x)}"` : '') + (o.y ? ` y="${n(o.y)}"` : '')
    this.cur.add(at, { raw: `<use href="#${id}"${xy}${o.transform ? ` transform="${o.transform}"` : ''}/>` })
  }

  stroke(pts: Pt[], penIn: PenName | PenSpec = 'ink', o: StrokeOpts = {}): StrokeResult {
    let P = resolvePen(penIn)
    if (this.knobs.bleed !== 1) P = { ...P, bleed: P.bleed * this.knobs.bleed }
    const r = this.next('s')
    const jr = r.fork('jit')
    const width = (o.width ?? 1) * this.knobs.width * (1 + jr.gauss(0, 0.05))
    const alpha = (o.alpha ?? 1) * (this.tier === 'hi' ? Math.min(1.08, Math.max(0.92, 1 + jr.gauss(0, 0.04))) : 1)
    const res = penStroke(pts, P, r, { ...o, tier: this.tier, wobble: (o.wobble ?? 1) * this.knobs.wobble, width, alpha })
    return this.put(res, P)
  }

  lines(lines: Line[], penIn: PenName | PenSpec = 'ink', o?: StrokeOpts): void {
    for (const l of lines) this.stroke(l.pts, l.pen ?? penIn, mergeOpts(l.o, o))
  }

  dot(cx: number, cy: number, r: number, penIn: PenName | PenSpec = 'ink', o: StrokeOpts = {}): void {
    const P = resolvePen(penIn)
    const res = penDot(cx, cy, r, P, this.next('d'), { ...o, tier: this.tier, width: (o.width ?? 1) * this.knobs.width })
    this.put(res, P)
  }

  private put(res: StrokeResult, P: PenSpec): StrokeResult {
    for (const L of res.layers) {
      const item: PathItem = { d: L.d, fill: L.fill, op: L.op, rule: L.rule }
      let mat: Material
      if (P.kind === 'felt') mat = (L.k === 'halo' || L.k === 'hair') && !this.leaned ? 'wash' : 'felt'
      else if (P.kind === 'pencil') mat = P.waxy ? 'waxy' : 'pencil'
      else mat = P.kind === 'marker' ? 'marker' : 'hl'
      this.cur.add(mat, item)
    }
    this.grow(res.bbox)
    return res
  }

  flat(material: Material, d: string, fill: PaintKey, op = 1, extra: { rule?: 'evenodd'; stroke?: PaintKey; sw?: number; bbox?: BBox; clip?: string } = {}): void {
    if (!d) return
    this.cur.add(material, { d, fill, op, rule: extra.rule, stroke: extra.stroke, sw: extra.sw, clip: extra.clip })
    if (extra.bbox) this.grow(extra.bbox)
  }

  poly(material: Material, pts: Pt[], fill: PaintKey, op = 1): void {
    if (pts.length < 3) return
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity
    for (const p of pts) {
      if (p[0] < x0) x0 = p[0]
      if (p[0] > x1) x1 = p[0]
      if (p[1] < y0) y0 = p[1]
      if (p[1] > y1) y1 = p[1]
    }
    this.flat(material, smoothClosed(pts, TIERS[this.tier]), fill, op, { bbox: [x0, y0, x1, y1] })
  }

  raw(svg: string, material: Material = 'text'): void {
    if (svg) this.cur.add(material, { raw: svg })
  }

  text(x: number, y: number, s: string, o: { size: number; fill?: PaintKey; font?: string; anchor?: 'start' | 'middle' | 'end'; weight?: number } = { size: 16 }): void {
    const attrs = `x="${n(x)}" y="${n(y)}" font-size="${n(o.size)}" fill="${paint(o.fill ?? 'ink')}" font-family="${esc(o.font ?? 'var(--font-hand, cursive)')}"` +
      (o.anchor ? ` text-anchor="${o.anchor}"` : '') + (o.weight ? ` font-weight="${o.weight}"` : '')
    this.raw(`<text ${attrs}>${esc(s)}</text>`, 'text')
  }

  private itemNodes(items: Item[]): Piece[] {
    const q = this.tier === 'lo' ? 50 : 100
    const merged = new Map<string, PathItem>()
    const seq: Array<PathItem | Piece> = []
    for (const it of items) {
      if ('raw' in it) {
        seq.push({ t: 'raw', s: it.raw })
      } else if ('scope' in it) {
        seq.push(this.groupNode(it.scope))
      } else if (it.rule || it.stroke) {
        seq.push(it)
      } else {
        const op = Math.round(it.op * q) / q
        const key = `${it.fill}|${op}|${it.clip ?? ''}`
        const m = merged.get(key)
        if (m) m.d += it.d
        else {
          const c = { ...it, op }
          merged.set(key, c)
          seq.push(c)
        }
      }
    }
    const out: Piece[] = []
    for (const it of seq) {
      if ('t' in it) {
        out.push(it)
        continue
      }
      const op = n(it.op, 100)
      const clip = it.clip ? ` clip-path="url(#${it.clip})"` : ''
      if (it.stroke) {
        out.push({ t: 'raw', s: `<path d="${it.d}" fill="none" stroke="${paint(it.stroke)}" stroke-width="${n(it.sw ?? 1)}" stroke-linecap="round" stroke-linejoin="round"${it.op < 0.995 ? ` stroke-opacity="${op}"` : ''}${clip}/>` })
      } else {
        out.push({ t: 'raw', s: `<path d="${it.d}" fill="${paint(it.fill)}"${it.op < 0.995 ? ` fill-opacity="${op}"` : ''}${it.rule ? ` fill-rule="${it.rule}"` : ''}${clip}/>` })
      }
    }
    return out
  }

  private scopeNodes(scope: Scope): Piece[] {
    const out: Piece[] = []
    for (const mat of ORDER) {
      const items = scope.buckets[mat]
      if (!items || !items.length) continue
      const kids = this.itemNodes(items)
      const grain = this.grain ? GRAIN_OF[mat] : undefined
      const blend = BLENDED.has(mat)
      if (!grain && !blend) out.push(...kids)
      else out.push({ t: 'mat', grain, blend, kids })
    }
    return out
  }

  private groupNode(scope: Scope): Piece {
    const a = scope.attrs ?? {}
    const kids = this.scopeNodes(scope)
    let pre = ''
    let attrs = ''
    if (a.clip) {
      const id = `ll-c${hashSeed(a.clip).toString(36)}`
      pre = `<clipPath id="${id}"><path d="${a.clip}"/></clipPath>`
      attrs += ` clip-path="url(#${id})"`
    }
    if (a.transform) attrs += ` transform="${a.transform}"`
    if (a.opacity !== undefined && a.opacity < 1) attrs += ` opacity="${n(a.opacity, 100)}"`
    if (a.id) attrs += ` id="${esc(a.id)}"`
    if (a.part) attrs += ` data-part="${esc(a.part)}"`
    if (a.hideOn) attrs += ` data-hide-on="${esc(a.hideOn)}"`
    if (a.mask) attrs += ` mask="url(#${esc(a.mask)})"`
    if (a.vars) attrs += ` style="${Object.entries(a.vars).map(([k, v]) => `--${k}:${n(v)}`).join(';')}"`
    const plain = !a.clip && !a.transform && !(a.opacity !== undefined && a.opacity < 1) && !a.id && !a.mask
    return { t: 'grp', pre, open: `<g${attrs}>`, kids, plain }
  }

  private static subtle(nd: Piece): nd is Extract<Piece, { t: 'mat' }> {
    return nd.t === 'mat' && !!nd.grain && SUBTLE.has(nd.grain) && nd.kids.every((k) => k.t === 'raw')
  }

  private static pure(nd: Piece): boolean {
    return nd.t === 'grp' && nd.plain && !nd.pre && nd.kids.length > 0 && nd.kids.every((k) => Ink.subtle(k) || Ink.pure(k))
  }

  private static bare(nd: Piece): Piece[] {
    if (nd.t === 'mat') return nd.kids
    if (nd.t === 'grp') return [{ ...nd, kids: nd.kids.flatMap((k) => Ink.bare(k)) }]
    return [nd]
  }

  private static grainsIn(nd: Piece, into: Array<{ grain?: GrainKind; blend: boolean }>): void {
    if (nd.t === 'mat') into.push({ grain: nd.grain, blend: nd.blend })
    else if (nd.t === 'grp') for (const k of nd.kids) Ink.grainsIn(k, into)
  }

  private leanMerge(nodes: Piece[]): Piece[] {
    const out: Piece[] = []
    let run: Piece[] = []
    const flush = (): void => {
      if (run.length < 2) {
        out.push(...run)
      } else {
        const found: Array<{ grain?: GrainKind; blend: boolean }> = []
        for (const r of run) Ink.grainsIn(r, found)
        out.push({ t: 'mat', grain: found.some((f) => f.grain === 'marker') ? 'marker' : 'felt', blend: found.some((f) => f.blend), kids: run.flatMap((r) => Ink.bare(r)) })
      }
      run = []
    }
    for (const nd of nodes) {
      if (Ink.subtle(nd) || Ink.pure(nd)) {
        run.push(nd)
      } else {
        flush()
        out.push(nd.t === 'grp' ? { ...nd, kids: this.leanMerge(nd.kids) } : nd)
      }
    }
    flush()
    return out
  }

  private static join(nodes: Piece[]): Piece[] {
    const out: Piece[] = []
    for (const nd of nodes) {
      const last = out[out.length - 1]
      if (nd.t === 'mat' && last && last.t === 'mat' && last.grain === nd.grain && last.blend === nd.blend) last.kids = [...last.kids, ...nd.kids]
      else out.push(nd.t === 'mat' ? { ...nd } : nd)
    }
    return out.map((nd) => (nd.t === 'grp' ? { ...nd, kids: Ink.join(nd.kids) } : nd))
  }

  private print(nodes: Piece[]): string {
    let out = ''
    for (const nd of nodes) {
      if (nd.t === 'raw') out += nd.s
      else if (nd.t === 'grp') out += `${nd.pre}${nd.open}${this.print(nd.kids)}</g>`
      else {
        const mask = nd.grain ? ` mask="url(#${maskId(nd.grain, this.variant)})"` : ''
        const style = nd.blend ? ` style="mix-blend-mode:${BLEND}"` : ''
        out += `<g${mask}${style}>${this.print(nd.kids)}</g>`
      }
    }
    return out
  }

  private emitScope(scope: Scope): string {
    let nodes = this.scopeNodes(scope)
    if (this.leaned && this.grain) nodes = this.leanMerge(nodes)
    return this.print(Ink.join(nodes))
  }

  toSvg(o: { w: number; h: number; pad?: number; layers?: LayerName[] }): InkResult {
    const names = [...this.roots.keys()].filter((k) => !o.layers || o.layers.includes(k))
    const parts: Partial<Record<LayerName, string>> = {}
    for (const name of names) parts[name] = this.emitScope(this.roots.get(name) as Scope)
    const b = this.bb
    const fin = (v: number): number => (Number.isFinite(v) ? v : 0)
    const bbox: BBox = [fin(b[0]), fin(b[1]), fin(b[2]), fin(b[3])]
    const excursion = Math.max(0, -bbox[0], -bbox[1], bbox[2] - o.w, bbox[3] - o.h)
    const pad = o.pad ?? Math.max(2, Math.ceil(excursion) + 1)
    const svg = names.length === 1 ? (parts[names[0]] as string) : names.map((k) => `<g data-layer="${k}">${parts[k]}</g>`).join('')
    return { svg, w: o.w, h: o.h, pad, layers: names, parts, bbox }
  }
}

export function inkViewBox(res: { w: number; h: number; pad: number }): string {
  return `${n(-res.pad)} ${n(-res.pad)} ${n(res.w + 2 * res.pad)} ${n(res.h + 2 * res.pad)}`
}

import type { Line, Material, PenName, PenSpec, Pt, StrokeOpts } from '@/lib/ink/types'
import type { Ink } from '@/lib/ink/builder'
import type { PaintKey } from '@/lib/ink/paint'
import { clamp, type Rng } from '@/lib/ink/rng'
import { noise1 } from '@/lib/ink/noise'
import { PathWriter, TAU, TIERS, area, bboxOf, centroid, densifyClosed, offsetPoly, scanSpans, seg, simplePath, smoothClosed, wobblePoly, xform } from '@/lib/ink/geom'
import { pen as resolvePen } from '@/lib/ink/pens'

export function misreg(poly: Pt[], rng: Rng, amt = 3, o: { bias?: number; tilt?: number; grow?: number } = {}): Pt[] {
  const ang = (o.bias ?? 0.75) + rng.gauss(0, 0.5)
  const k = amt * rng.range(0.7, 1.15)
  const b = bboxOf(poly)
  const bw = b[2] - b[0], bh = b[3] - b[1]
  const keep = Math.min(1, 120 / Math.max(bw, bh, 1))
  const sc = 1 + rng.gauss(0, 0.012) * keep + (o.grow ?? 0) / Math.max(10, Math.min(bw, bh))
  return xform(poly, {
    dx: Math.cos(ang) * k,
    dy: Math.sin(ang) * k,
    rot: clamp(rng.gauss(0, 0.014), -0.03, 0.03) * (o.tilt ?? 1) * Math.min(1, 40 / Math.max(20, Math.max(bw, bh))),
    sx: sc,
    sy: sc + rng.gauss(0, 0.01) * keep,
  })
}

export const defaultMis = (poly: Pt[]): number => {
  const b = bboxOf(poly)
  return clamp(Math.min(b[2] - b[0], b[3] - b[1]) * 0.11, 1.6, 6)
}

export interface Offset {
  dx: number
  dy: number
}

const shiftOf = (from: Pt[], to: Pt[]): Offset => {
  const a = centroid(from), b = centroid(to)
  return { dx: b[0] - a[0], dy: b[1] - a[1] }
}

function laid(_ink: Ink, poly: Pt[], _mis: number | false | undefined, _salt = 'mr'): Pt[] {
  return poly
}

export function rough(poly: Pt[], rng: Rng, amt = 0.8, step = 4): Pt[] {
  const pts = densifyClosed(poly, step)
  let per = 0
  for (let i = 0; i < pts.length; i++) per += Math.hypot(pts[(i + 1) % pts.length][0] - pts[i][0], pts[(i + 1) % pts.length][1] - pts[i][1])
  const nz = noise1(rng, per + 60, 22), nz2 = noise1(rng, per + 60, 6)
  const sgn = area(pts) >= 0 ? 1 : -1
  let s = 0
  return pts.map((p, i) => {
    const q = pts[(i + 1) % pts.length], r = pts[(i - 1 + pts.length) % pts.length]
    const tx = q[0] - r[0], ty = q[1] - r[1]
    const l = Math.hypot(tx, ty) || 1
    if (i) s += Math.hypot(p[0] - pts[i - 1][0], p[1] - pts[i - 1][1])
    const off = amt * (nz(s) * 0.8 + nz2(s) * 0.5)
    return [p[0] + (ty / l) * sgn * off, p[1] - (tx / l) * sgn * off]
  })
}

export function solidFill(ink: Ink, poly: Pt[], color: PaintKey, o: { alpha?: number; inset?: number; rough?: number; material?: Material } = {}): Offset {
  const rng = ink.next('solid')
  const inner = o.inset ? offsetPoly(poly, -o.inset, 0, 0) : poly
  ink.poly(o.material ?? 'marker', rough(inner, rng, o.rough ?? 0.1, 4), color, o.alpha ?? 0.94)
  return { dx: 0, dy: 0 }
}

export function flatFill(ink: Ink, poly: Pt[], color: PaintKey, alpha = 0.5, material: Material = 'marker'): void {
  if (poly.length < 3) return
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity
  for (const p of poly) {
    if (p[0] < x0) x0 = p[0]
    if (p[0] > x1) x1 = p[0]
    if (p[1] < y0) y0 = p[1]
    if (p[1] > y1) y1 = p[1]
  }
  const d = 'M' + poly.map((p) => `${p[0].toFixed(2)} ${p[1].toFixed(2)}`).join('L') + 'Z'
  ink.flat(material, d, color, alpha, { bbox: [x0, y0, x1, y1] })
}

const solidAlpha = (alpha: number | undefined, fallback: number, passes = 1): number => clamp((alpha ?? fallback) * (passes > 1 ? 1.14 : 1.08), 0.3, 0.96)

const MAX_BAND_POINTS = 72

export function bandPoly(a: Pt, b: Pt, width: number, rng: Rng, chisel = 0.34, maxPts = MAX_BAND_POINTS): Pt[] {
  const dx = b[0] - a[0], dy = b[1] - a[1]
  const L = Math.hypot(dx, dy) || 1
  const ux = dx / L, uy = dy / L, nx = -uy, ny = ux
  const hw = width / 2
  const sk = Math.min(0.45 * L, chisel * width) * (rng() < 0.5 ? 1 : -1)
  const amp = clamp(0.035 * width + 0.0022 * L, 0.12, 0.65)
  const p1 = rng() * TAU, p2 = rng() * TAU, p3 = rng() * TAU, p4 = rng() * TAU
  const cnt = clamp(Math.ceil(L / 4), 3, maxPts)
  const left: Pt[] = [], right: Pt[] = []
  for (let i = 0; i <= cnt; i++) {
    const t = i / cnt
    const wl = amp * (Math.sin(5.1 * t + p1) + 0.4 * Math.sin(13.7 * t + p2))
    const wr = amp * (Math.sin(5.1 * t + p3) + 0.4 * Math.sin(13.7 * t + p4))
    const cx = a[0] + dx * t, cy = a[1] + dy * t
    left.push([cx + nx * (hw + wl), cy + ny * (hw + wl)])
    right.push([cx - nx * (hw + wr), cy - ny * (hw + wr)])
  }
  left[0] = [left[0][0] + ux * sk, left[0][1] + uy * sk]
  right[0] = [right[0][0] - ux * sk, right[0][1] - uy * sk]
  left[cnt] = [left[cnt][0] + ux * sk, left[cnt][1] + uy * sk]
  right[cnt] = [right[cnt][0] - ux * sk, right[cnt][1] - uy * sk]
  return left.concat(right.reverse())
}

export interface BandOpts {
  alpha?: number
  mis?: number | false
  passes?: 1 | 2
  angle?: number
  W?: number
  overlap?: number
  ends?: 'loose' | 'flag' | 'square'
  material?: Material
}

const BAR = 4.4

const REACH = 380

export function bandFill(ink: Ink, poly: Pt[], color: PaintKey, o: BandOpts = {}): Offset {
  return solidFill(ink, poly, color, { alpha: solidAlpha(o.alpha, 0.85, o.passes ?? 1), material: o.material })
}

export interface ClipOpts {
  alpha?: number
  mis?: number | false
  W?: number
  angle?: number
  overlap?: number
  rough?: number
  rim?: boolean
  material?: Material
}

export function clipFill(ink: Ink, poly: Pt[], color: PaintKey, o: ClipOpts = {}): Offset {
  return solidFill(ink, poly, color, { alpha: solidAlpha(o.alpha, 0.92), rough: Math.min(o.rough ?? 0.3, 0.3), material: o.material, inset: 0 })
}

export interface BlobOpts {
  alpha?: number
  mis?: number | false
  rough?: number
  material?: Material
}

export function blobFill(ink: Ink, poly: Pt[], color: PaintKey, o: BlobOpts = {}): Offset {
  const rng = ink.next('blob')
  const at = laid(ink, poly, o.mis)
  ink.poly(o.material ?? 'marker', rough(at, rng, Math.min(o.rough ?? 0.1, 0.12), 4), color, Math.max(o.alpha ?? 0.9, 0.92))
  return shiftOf(poly, at)
}

export function wash(ink: Ink, poly: Pt[], color: PaintKey, o: { alpha?: number; inset?: number; shift?: number; wobble?: number; material?: Material } = {}): Offset {
  const rng = ink.next('wash')
  const b = bboxOf(poly)
  const size = Math.max(b[2] - b[0], b[3] - b[1])
  const dn = o.shift ?? 0.007 * size + 0.3
  const P = wobblePoly(densifyClosed(offsetPoly(poly, -(o.inset ?? 0.9), dn * 0.85 * ink.knobs.misreg, dn * ink.knobs.misreg), 4), rng, (o.wobble ?? 0.7) * ink.knobs.wobble, 18)
  ink.poly(o.material ?? 'marker', P, color, o.alpha ?? 0.5)
  return { dx: dn * 0.85 * ink.knobs.misreg, dy: dn * ink.knobs.misreg }
}

function loosen(a: Pt, b: Pt, rng: Rng, over: number, under: number, cap = 0.3): [Pt, Pt] {
  const L = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1
  const t: Pt = [(b[0] - a[0]) / L, (b[1] - a[1]) / L]
  const ext = (): number => (rng() < 0.3 ? -rng() * under : rng() * over)
  const e0 = Math.max(ext(), -cap * L), e1 = Math.max(ext(), -cap * L)
  return [[a[0] - t[0] * e0, a[1] - t[1] * e0], [b[0] + t[0] * e1, b[1] + t[1] * e1]]
}

export interface HatchOpts {
  angle?: number
  gap?: number
  cross?: boolean | number
  tones?: 1 | 2 | 3
  over?: number
  under?: number
  skip?: number
  pen?: PenName | PenSpec
  alpha?: number
  width?: number
  opts?: StrokeOpts
}

export function hatch(ink: Ink, region: Pt[] | [number, number, number, number], o: HatchOpts = {}): void {
  const rng = ink.next('hatch')
  const poly: Pt[] = region.length === 4 && typeof region[0] === 'number'
    ? ((r: [number, number, number, number]) => [[r[0], r[1]], [r[0] + r[2], r[1]], [r[0] + r[2], r[1] + r[3]], [r[0], r[1] + r[3]]] as Pt[])(region as [number, number, number, number])
    : (region as Pt[])
  const gap = o.gap ?? 4
  const a0 = (o.angle ?? 60) + rng.gauss(0, 1.2)
  const tones = o.tones ?? (o.cross ? 2 : 1)
  const crossOff = typeof o.cross === 'number' ? o.cross : 78
  const passes = [a0, ...(tones >= 2 ? [a0 + crossOff] : []), ...(tones >= 3 ? [a0 + crossOff / 2 + 8] : [])]
  passes.forEach((deg, pi) => {
    const g = gap * (pi ? 1.3 : 1)
    const spans = scanSpans(poly, (deg * Math.PI) / 180, g, rng, { jitter: 0.15, even: false })
    const lines: Line[] = []
    let flip = false
    for (const sp of spans) {
      if (o.skip && rng.chance(o.skip)) continue
      let [la, lb] = loosen(sp.a, sp.b, rng, o.over ?? 1.6, o.under ?? 1.4)
      flip = !flip
      if (flip) [la, lb] = [lb, la]
      const mid: Pt = [(la[0] + lb[0]) / 2 + rng.gauss(0, 0.25), (la[1] + lb[1]) / 2 + rng.gauss(0, 0.25)]
      lines.push({ pts: [la, mid, lb], o: { simple: true, end: 'flick', start: rng.chance(0.4) ? 'pool' : 'soft', speed: 1.3, wobble: 0.5, width: (o.width ?? 1) * rng.range(0.85, 1.15), alpha: o.alpha ?? 0.85 } })
    }
    ink.lines(lines, o.pen ?? 'pencil', o.opts)
  })
}

export function edgeBand(ink: Ink, x: number, y: number, w: number, h: number, side: 't' | 'r' | 'b' | 'l', o: { thick?: number; gap?: number; inset?: number; pen?: PenName | PenSpec; alpha?: number; width?: number } = {}): void {
  const R = ink.next('edge')
  const thick = o.thick ?? 4
  const gap = o.gap ?? 2.6
  const horiz = side === 'b' || side === 't'
  const len = horiz ? w : h
  const dirSign = side === 'b' || side === 'r' ? 1 : -1
  const inset = o.inset ?? 2
  let t = R.range(0, gap) + inset
  const end = len - inset
  let inCluster = R.int(3, 7), cl = 0
  const lines: Line[] = []
  while (t < end) {
    const fade = Math.min(1, t / 9, (len - t) / 9)
    const bell = 0.55 + 0.45 * Math.sin((Math.PI * (cl + 0.5)) / inCluster)
    const L = thick * (0.45 + 0.55 * fade) * bell * R.range(0.65, 1.2)
    const lean = R.range(0.55, 1.2) * L
    let p0: Pt, p1: Pt
    if (horiz) {
      const by = side === 'b' ? y + h : y
      const x0 = x + t
      p0 = [x0 + R.gauss(0, 0.3), by - dirSign * R.range(0, 1)]
      p1 = [x0 - lean * 0.7, by + dirSign * L]
    } else {
      const bx = side === 'r' ? x + w : x
      const y0 = y + t
      p0 = [bx - dirSign * R.range(0, 1), y0 + R.gauss(0, 0.3)]
      p1 = [bx + dirSign * L, y0 + lean * 0.7]
    }
    lines.push({ pts: seg(p0[0], p0[1], p1[0], p1[1], R.gauss(0, 0.2), 3), o: { simple: true, start: 'soft', end: 'flick', speed: 1.5, wobble: 0.5, alpha: o.alpha ?? 0.82, width: o.width ?? 0.62 } })
    cl++
    t += gap * R.range(0.75, 1.3)
    if (cl >= inCluster) {
      cl = 0
      inCluster = R.int(3, 7)
      t += gap * R.range(0.8, 2.2)
    }
  }
  ink.lines(lines, o.pen ?? 'ink.fine')
}

export function stipple(ink: Ink, x: number, y: number, w: number, h: number, count: number, o: { pen?: PenName | PenSpec; alpha?: number } = {}): void {
  const R = ink.next('stip')
  const lines: Line[] = []
  for (let i = 0; i < count; i++) {
    const px = x + R() * w, py = y + R() * h
    lines.push({ pts: [[px, py], [px + R.range(-0.5, 0.5), py + R.range(0.2, 0.9)]], o: { simple: true, width: R.range(0.8, 1.5), start: 'pool', end: 'pool', wobble: 0, alpha: o.alpha } })
  }
  ink.lines(lines, o.pen ?? 'ink.fine')
}

export function contourArcs(ink: Ink, cx: number, cy: number, rx: number, ry: number, o: { n?: number; dir?: 1 | -1; pen?: PenName | PenSpec; alpha?: number } = {}): void {
  const cnt = o.n ?? 4
  const lines: Line[] = []
  for (let i = 0; i < cnt; i++) {
    const t = (i + 0.6) / (cnt + 0.2)
    const y = cy - ry + 2 * ry * t
    const half = rx * Math.sqrt(Math.max(0, 1 - Math.pow((y - cy) / ry, 2)))
    const bulge = ry * 0.28 * (1 - t) + 1
    lines.push({ pts: seg(cx - half * 0.92, y, cx + half * 0.92, y, bulge * (o.dir ?? 1), 6), o: { simple: true, width: 0.75, start: 'soft', end: 'flick', speed: 1.3, wobble: 0.5, alpha: o.alpha } })
  }
  ink.lines(lines, o.pen ?? 'ink.fine')
}

export function highlight(ink: Ink, x: number, y: number, w: number, h: number, o: { pen?: PenName | PenSpec; k?: number; opts?: StrokeOpts } = {}): void {
  const rng = ink.next('hl')
  const cy = y + h / 2
  const x1 = x - (1 + rng() * 3), x2 = x + w + 1 + rng() * 4
  const y1 = cy + rng.gauss(0, 0.04 * h), y2 = cy + rng.gauss(0, 0.05 * h) - 0.004 * w
  const mid: Pt = [(x1 + x2) / 2, (y1 + y2) / 2 + rng.gauss(0, 0.04 * h)]
  const P = resolvePen(o.pen ?? 'hi')
  ink.stroke([[x1, y1], mid, [x2, y2]], P, { width: (h * (o.k ?? 0.86)) / P.W, end: rng() < 0.5 ? 'flick' : 'pool', start: 'pool', wobble: 0.6, ...o.opts })
}

function markerBand(ink: Ink, a: Pt, b: Pt, width: number, color: PaintKey, alpha: number, o: { chisel?: number; pool?: boolean } = {}): void {
  const rng = ink.next('mb')
  const cfg = TIERS[ink.tier]
  const L = Math.hypot(b[0] - a[0], b[1] - a[1])
  if (L < 1) return
  const t: Pt = [(b[0] - a[0]) / L, (b[1] - a[1]) / L], nn: Pt = [-t[1], t[0]]
  const hw = width / 2
  const sk = Math.min(0.45 * L, (o.chisel ?? 0.36) * width) * (rng() < 0.5 ? 1 : -1)
  const amp = clamp(0.04 * width + 0.0025 * L, 0.12, 0.7)
  const p1 = rng.range(0, TAU), p2 = rng.range(0, TAU), p3 = rng.range(0, TAU), p4 = rng.range(0, TAU)
  const cnt = Math.max(3, Math.ceil(L / 3))
  const bulge = Math.min(0.16 * width, 0.1 * L)
  const top: Pt[] = [], bot: Pt[] = []
  for (let i = 0; i <= cnt; i++) {
    const u = i / cnt
    const w1 = amp * (Math.sin(5.1 * u * (L / 40 + 1) + p1) + 0.4 * Math.sin(13.7 * u + p2))
    const w2 = amp * (Math.sin(5.1 * u * (L / 40 + 1) + p3) + 0.4 * Math.sin(13.7 * u + p4))
    const bl = Math.sin(Math.PI * u) ** 0.35
    const cx = a[0] + t[0] * L * u, cy = a[1] + t[1] * L * u
    top.push([cx + nn[0] * (hw + w1) + t[0] * (sk / 2) - t[0] * bulge * (1 - bl), cy + nn[1] * (hw + w1) + t[1] * (sk / 2) - t[1] * bulge * (1 - bl)])
    bot.push([cx - nn[0] * (hw + w2) - t[0] * (sk / 2) + t[0] * bulge * (1 - bl), cy - nn[1] * (hw + w2) - t[1] * (sk / 2) + t[1] * bulge * (1 - bl)])
  }
  const poly = [...top, ...bot.reverse()]
  let d = smoothClosed(poly, cfg)
  let rule: 'evenodd' | undefined
  if (width > 5 && L > 1.6 * width && rng() < 0.6) {
    const w = new PathWriter(cfg.q)
    const slits = rng() < 0.4 ? 2 : 1
    for (let s = 0; s < slits; s++) {
      const u0 = rng.range(0.2, 0.6), u1 = Math.min(0.94, u0 + rng.range(0.2, 0.4))
      const off = rng.range(-0.28, 0.28) * width
      const m = 8
      const at = (u: number, k: number, sgn: number): Pt => [a[0] + t[0] * L * u + nn[0] * (off + sgn * 0.3 * Math.sin(Math.PI * k)), a[1] + t[1] * L * u + nn[1] * (off + sgn * 0.3 * Math.sin(Math.PI * k))]
      for (let i = 0; i <= m; i++) {
        const p = at(u0 + (u1 - u0) * (i / m), i / m, 1)
        if (i) w.L(p[0], p[1])
        else w.M(p[0], p[1])
      }
      for (let i = m; i >= 0; i--) {
        const p = at(u0 + (u1 - u0) * (i / m), i / m, -1)
        w.L(p[0], p[1])
      }
      w.Z()
    }
    d += w.d
    rule = 'evenodd'
  }
  const bb = bboxOf(poly)
  ink.flat('marker', d, color, alpha, { rule, bbox: bb })
  ink.flat('marker', smoothClosed(poly, cfg), color, alpha * 0.32, { stroke: color, sw: clamp(0.08 * width, 0.6, 1.1) })
  if (o.pool !== false) {
    const r0 = Math.min(0.5 * width, 0.35 * L)
    const pool = (p: Pt, dir: 1 | -1, op: number): void => {
      const l = r0 * 0.5
      const q = (u: number, v: number): Pt => [p[0] + t[0] * (u * dir) + nn[0] * v + t[0] * ((Math.sign(v) * sk) / 2), p[1] + t[1] * (u * dir) + nn[1] * v + t[1] * ((Math.sign(v) * sk) / 2)]
      ink.flat('marker', smoothClosed([q(0, hw * 0.92), q(l, hw * 0.92), q(l, -hw * 0.92), q(0, -hw * 0.92)], cfg), color, op)
    }
    pool(a, 1, alpha * 0.2)
    pool(b, -1, alpha * 0.26)
  }
}

export interface PolyFillOpts {
  alpha?: number
  mis?: number | false
  angle?: number
  pw?: number
  overlap?: number
}

export function polyFill(ink: Ink, poly: Pt[], color: PaintKey, o: PolyFillOpts = {}): Offset {
  return solidFill(ink, poly, color, { alpha: clamp((o.alpha ?? 0.5) * 1.8, 0.3, 0.96) })
}

export function sweepFill(ink: Ink, x: number, y: number, w: number, h: number, color: PaintKey, o: { alpha?: number; pw?: number; overlap?: number; mis?: number | false } = {}): Offset {
  return solidFill(ink, [[x, y], [x + w, y], [x + w, y + h], [x, y + h]], color, { alpha: clamp((o.alpha ?? 0.48) * 1.9, 0.3, 0.96) })
}

import type { BBox, Pt, Tier } from '@/lib/ink/types'
import { fmtUnits, type Q } from '@/lib/ink/paint'
import { clamp, type Rng } from '@/lib/ink/rng'
import { noise1 } from '@/lib/ink/noise'

export const TAU = Math.PI * 2

export interface TierCfg {
  q: Q
  tol: number
  stepK: number
}

export const TIERS: Record<Tier, TierCfg> = {
  hi: { q: 20, tol: 0.085, stepK: 1 },
  lo: { q: 10, tol: 0.16, stepK: 1.5 },
}

const mixPt = (a: Pt, b: Pt, t: number): Pt => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]

export function seg(x1: number, y1: number, x2: number, y2: number, bow = 0, cnt = 8): Pt[] {
  const dx = x2 - x1, dy = y2 - y1
  const len = Math.hypot(dx, dy) || 1
  const nx = -dy / len, ny = dx / len
  const out: Pt[] = []
  for (let i = 0; i <= cnt; i++) {
    const t = i / cnt
    const b = bow * Math.sin(Math.PI * t)
    out.push([x1 + dx * t + nx * b, y1 + dy * t + ny * b])
  }
  return out
}

export function densify(pts: Pt[], step = 1.5): Pt[] {
  const out: Pt[] = [[pts[0][0], pts[0][1]]]
  for (let i = 1; i < pts.length; i++) {
    const a = pts[i - 1], b = pts[i]
    const c = Math.max(1, Math.ceil(Math.hypot(b[0] - a[0], b[1] - a[1]) / step))
    for (let k = 1; k <= c; k++) out.push(mixPt(a, b, k / c))
  }
  return out
}

export function spline(pts: Pt[], step = 1.5): Pt[] {
  if (pts.length < 3) return densify(pts, step)
  const out: Pt[] = []
  const first = pts[0], second = pts[1], last = pts[pts.length - 1], prev = pts[pts.length - 2]
  const P: Pt[] = [[first[0] - (second[0] - first[0]), first[1] - (second[1] - first[1])], ...pts, [last[0] + (last[0] - prev[0]), last[1] + (last[1] - prev[1])]]
  for (let i = 1; i < P.length - 2; i++) {
    const p0 = P[i - 1], p1 = P[i], p2 = P[i + 1], p3 = P[i + 2]
    const d01 = Math.max(1e-3, Math.hypot(p1[0] - p0[0], p1[1] - p0[1]) ** 0.5)
    const d12 = Math.max(1e-3, Math.hypot(p2[0] - p1[0], p2[1] - p1[1]) ** 0.5)
    const d23 = Math.max(1e-3, Math.hypot(p3[0] - p2[0], p3[1] - p2[1]) ** 0.5)
    const cnt = Math.max(2, Math.ceil(Math.hypot(p2[0] - p1[0], p2[1] - p1[1]) / step))
    const t1 = d01, t2 = d01 + d12, t3 = d01 + d12 + d23
    for (let k = 0; k < cnt; k++) {
      const u = t1 + (t2 - t1) * (k / cnt)
      const A1 = mixPt(p0, p1, u / t1)
      const A2 = mixPt(p1, p2, (u - t1) / (t2 - t1))
      const A3 = mixPt(p2, p3, (u - t2) / (t3 - t2))
      const B1 = mixPt(A1, A2, u / t2)
      const B2 = mixPt(A2, A3, (u - t1) / (t3 - t1))
      out.push(mixPt(B1, B2, (u - t1) / (t2 - t1)))
    }
  }
  out.push([last[0], last[1]])
  return out
}

export function fillet(pts: Pt[], r: number): Pt[] {
  if (pts.length < 3 || r <= 0) return pts
  const out: Pt[] = [pts[0]]
  for (let i = 1; i < pts.length - 1; i++) {
    const a = pts[i - 1], b = pts[i], c = pts[i + 1]
    const l1 = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1
    const l2 = Math.hypot(c[0] - b[0], c[1] - b[1]) || 1
    const rr = Math.min(r, l1 * 0.45, l2 * 0.45)
    const p1: Pt = [b[0] + ((a[0] - b[0]) / l1) * rr, b[1] + ((a[1] - b[1]) / l1) * rr]
    const p2: Pt = [b[0] + ((c[0] - b[0]) / l2) * rr, b[1] + ((c[1] - b[1]) / l2) * rr]
    for (let k = 0; k <= 5; k++) {
      const t = k / 5, u = 1 - t
      out.push([u * u * p1[0] + 2 * u * t * b[0] + t * t * p2[0], u * u * p1[1] + 2 * u * t * b[1] + t * t * p2[1]])
    }
  }
  out.push(pts[pts.length - 1])
  return out
}

export function rounded(verts: Pt[], rad: number, rng: Rng, per = 5): Pt[] {
  const out: Pt[] = [[verts[0][0], verts[0][1]]]
  for (let i = 1; i < verts.length - 1; i++) {
    const P = verts[i - 1], V = verts[i], N = verts[i + 1]
    const l1 = Math.hypot(P[0] - V[0], P[1] - V[1]) || 1
    const l2 = Math.hypot(N[0] - V[0], N[1] - V[1]) || 1
    const r = Math.min(rad * (0.75 + rng() * 0.5), l1 * 0.48, l2 * 0.48)
    if (r < 0.6) {
      out.push([V[0], V[1]])
      continue
    }
    const a: Pt = [V[0] + ((P[0] - V[0]) / l1) * r, V[1] + ((P[1] - V[1]) / l1) * r]
    const b: Pt = [V[0] + ((N[0] - V[0]) / l2) * r, V[1] + ((N[1] - V[1]) / l2) * r]
    const k = 0.9 + rng() * 0.1
    const c: Pt = [V[0] * k + ((a[0] + b[0]) / 2) * (1 - k), V[1] * k + ((a[1] + b[1]) / 2) * (1 - k)]
    for (let j = 0; j <= per; j++) {
      const t = j / per, u = 1 - t
      out.push([u * u * a[0] + 2 * u * t * c[0] + t * t * b[0], u * u * a[1] + 2 * u * t * c[1] + t * t * b[1]])
    }
  }
  const e = verts[verts.length - 1]
  out.push([e[0], e[1]])
  return out
}

export function pathLength(pts: Pt[]): number {
  let L = 0
  for (let i = 1; i < pts.length; i++) L += Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1])
  return L
}

export interface Resampled {
  X: Float64Array
  Y: Float64Array
  S: Float64Array
  L: number
}

export function resample(P: Pt[], step: number): Resampled {
  const cum = [0]
  for (let i = 1; i < P.length; i++) cum.push(cum[i - 1] + Math.hypot(P[i][0] - P[i - 1][0], P[i][1] - P[i - 1][1]))
  const L = cum[cum.length - 1]
  const cnt = Math.max(2, Math.round(L / step) + 1)
  const X = new Float64Array(cnt), Y = new Float64Array(cnt), S = new Float64Array(cnt)
  let j = 0
  for (let i = 0; i < cnt; i++) {
    const s = (L * i) / (cnt - 1)
    while (j < P.length - 2 && cum[j + 1] < s) j++
    const seglen = cum[j + 1] - cum[j] || 1
    const t = clamp((s - cum[j]) / seglen, 0, 1)
    const a = P[j], b = P[Math.min(j + 1, P.length - 1)]
    X[i] = a[0] + (b[0] - a[0]) * t
    Y[i] = a[1] + (b[1] - a[1]) * t
    S[i] = s
  }
  return { X, Y, S, L }
}

export function simplifyClosed(pts: Pt[], tol: number): Pt[] {
  const m = pts.length
  if (m < 12 || tol <= 0) return pts
  let far = 0, fd = -1
  for (let i = 1; i < m; i++) {
    const d = (pts[i][0] - pts[0][0]) ** 2 + (pts[i][1] - pts[0][1]) ** 2
    if (d > fd) { fd = d; far = i }
  }
  const keep = new Uint8Array(m)
  keep[0] = keep[far] = 1
  const rec = (a: number, b: number): void => {
    const len = (b - a + m) % m
    if (len < 2) return
    const ax = pts[a][0], ay = pts[a][1], bx = pts[b][0], by = pts[b][1]
    const dx = bx - ax, dy = by - ay, l2 = dx * dx + dy * dy || 1e-9
    let md = -1, mi = -1
    for (let k = 1; k < len; k++) {
      const i = (a + k) % m
      const t = Math.max(0, Math.min(1, ((pts[i][0] - ax) * dx + (pts[i][1] - ay) * dy) / l2))
      const d = Math.hypot(pts[i][0] - (ax + t * dx), pts[i][1] - (ay + t * dy))
      if (d > md) { md = d; mi = i }
    }
    if (md > tol) { keep[mi] = 1; rec(a, mi); rec(mi, b) }
  }
  rec(0, far)
  rec(far, 0)
  const out: Pt[] = []
  for (let i = 0; i < m; i++) if (keep[i]) out.push(pts[i])
  return out
}

export class PathWriter {
  d = ''
  private cmd = ''
  private px = 0
  private py = 0
  private sx = 0
  private sy = 0
  private lastNum = ''
  private readonly q: Q

  constructor(q: Q) {
    this.q = q
  }

  private u(v: number): number {
    return Number.isFinite(v) ? Math.round(v * this.q) : 0
  }

  private num(k: number): void {
    const s = fmtUnits(k, this.q)
    if (this.lastNum) {
      const c = s.charCodeAt(0)
      if (!(c === 45 || (c === 46 && this.lastNum.includes('.')))) this.d += ' '
    }
    this.d += s
    this.lastNum = s
  }

  private letter(c: string): void {
    if (this.cmd !== c) {
      this.d += c
      this.cmd = c
      this.lastNum = ''
    }
  }

  M(x: number, y: number): this {
    const X = this.u(x), Y = this.u(y)
    this.d += 'M'
    this.cmd = 'M'
    this.lastNum = ''
    this.num(X)
    this.num(Y)
    this.px = this.sx = X
    this.py = this.sy = Y
    return this
  }

  L(x: number, y: number): this {
    const X = this.u(x), Y = this.u(y)
    this.letter('l')
    this.num(X - this.px)
    this.num(Y - this.py)
    this.px = X
    this.py = Y
    return this
  }

  Q(cx: number, cy: number, x: number, y: number): this {
    const CX = this.u(cx), CY = this.u(cy), X = this.u(x), Y = this.u(y)
    this.letter('q')
    this.num(CX - this.px)
    this.num(CY - this.py)
    this.num(X - this.px)
    this.num(Y - this.py)
    this.px = X
    this.py = Y
    return this
  }

  Z(): this {
    this.d += 'z'
    this.cmd = 'z'
    this.lastNum = ''
    this.px = this.sx
    this.py = this.sy
    return this
  }
}

export function smoothClosed(pts: Pt[], cfg: TierCfg): string {
  const p = simplifyClosed(pts, cfg.tol)
  const m = p.length
  if (m < 3) return ''
  const w = new PathWriter(cfg.q)
  w.M((p[m - 1][0] + p[0][0]) / 2, (p[m - 1][1] + p[0][1]) / 2)
  for (let i = 0; i < m; i++) {
    const a = p[i], b = p[(i + 1) % m]
    w.Q(a[0], a[1], (a[0] + b[0]) / 2, (a[1] + b[1]) / 2)
  }
  return w.Z().d
}

export function simplePath(pts: Pt[], cfg: TierCfg): string {
  const p = simplifyClosed(pts, cfg.tol)
  if (p.length < 3) return ''
  const w = new PathWriter(cfg.q)
  w.M(p[0][0], p[0][1])
  for (let i = 1; i < p.length; i++) w.L(p[i][0], p[i][1])
  return w.Z().d
}

export function polyPath(pts: Pt[], q: Q = 20): string {
  if (pts.length < 3) return ''
  const w = new PathWriter(q)
  w.M(pts[0][0], pts[0][1])
  for (let i = 1; i < pts.length; i++) w.L(pts[i][0], pts[i][1])
  return w.Z().d
}

export function area(pts: Pt[]): number {
  let a = 0
  for (let i = 0; i < pts.length; i++) {
    const p = pts[i], q = pts[(i + 1) % pts.length]
    a += p[0] * q[1] - q[0] * p[1]
  }
  return a / 2
}

export function bboxOf(pts: readonly Pt[]): BBox {
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity
  for (const p of pts) {
    if (p[0] < x0) x0 = p[0]
    if (p[0] > x1) x1 = p[0]
    if (p[1] < y0) y0 = p[1]
    if (p[1] > y1) y1 = p[1]
  }
  return [x0, y0, x1, y1]
}

export function centroid(poly: Pt[]): Pt {
  let a = 0, cx = 0, cy = 0
  for (let i = 0; i < poly.length; i++) {
    const [x0, y0] = poly[i]
    const [x1, y1] = poly[(i + 1) % poly.length]
    const c = x0 * y1 - x1 * y0
    a += c
    cx += (x0 + x1) * c
    cy += (y0 + y1) * c
  }
  if (Math.abs(a) < 1e-6) {
    const b = bboxOf(poly)
    return [(b[0] + b[2]) / 2, (b[1] + b[3]) / 2]
  }
  return [cx / (3 * a), cy / (3 * a)]
}

export function inside(pts: Pt[], x: number, y: number): boolean {
  let c = false
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
    const a = pts[i], b = pts[j]
    if (a[1] > y !== b[1] > y && x < ((b[0] - a[0]) * (y - a[1])) / (b[1] - a[1]) + a[0]) c = !c
  }
  return c
}

export function xform(pts: Pt[], o: { dx?: number; dy?: number; rot?: number; sx?: number; sy?: number; about?: Pt } = {}): Pt[] {
  const { dx = 0, dy = 0, rot = 0, sx = 1, sy = sx } = o
  const [cx, cy] = o.about ?? centroid(pts)
  const c = Math.cos(rot), s = Math.sin(rot)
  return pts.map(([x, y]) => {
    const px = (x - cx) * sx, py = (y - cy) * sy
    return [cx + px * c - py * s + dx, cy + px * s + py * c + dy]
  })
}

export function roundRectPoly(x: number, y: number, w: number, h: number, r = 0, per = 5): Pt[] {
  r = Math.min(r, w / 2, h / 2)
  if (r < 0.3) return [[x, y], [x + w, y], [x + w, y + h], [x, y + h]]
  const pts: Pt[] = []
  const arc = (cx: number, cy: number, a0: number): void => {
    for (let i = 0; i <= per; i++) {
      const a = a0 + (i / per) * (Math.PI / 2)
      pts.push([cx + Math.cos(a) * r, cy + Math.sin(a) * r])
    }
  }
  arc(x + w - r, y + r, -Math.PI / 2)
  arc(x + w - r, y + h - r, 0)
  arc(x + r, y + h - r, Math.PI / 2)
  arc(x + r, y + r, Math.PI)
  return pts
}

export function rectPoly(x: number, y: number, w: number, h: number, r = 0, per = 5): Pt[] {
  return roundRectPoly(x, y, w, h, r, per)
}

export function pillPoly(x: number, y: number, w: number, h: number, per = 7): Pt[] {
  return roundRectPoly(x, y, w, h, h / 2, per)
}

export function ellipsePoly(cx: number, cy: number, rx: number, ry: number, cnt = 28, rot = 0): Pt[] {
  const pts: Pt[] = []
  const c = Math.cos(rot), s = Math.sin(rot)
  for (let i = 0; i < cnt; i++) {
    const a = (i / cnt) * TAU
    const x = Math.cos(a) * rx, y = Math.sin(a) * ry
    pts.push([cx + x * c - y * s, cy + x * s + y * c])
  }
  return pts
}

export function densifyClosed(pts: Pt[], step = 4): Pt[] {
  const out: Pt[] = []
  for (let i = 0; i < pts.length; i++) {
    const a = pts[i], b = pts[(i + 1) % pts.length]
    const c = Math.max(1, Math.ceil(Math.hypot(b[0] - a[0], b[1] - a[1]) / step))
    for (let k = 0; k < c; k++) out.push([a[0] + ((b[0] - a[0]) * k) / c, a[1] + ((b[1] - a[1]) * k) / c])
  }
  return out
}

export function wobblePoly(pts: Pt[], rng: Rng, amp: number, wl = 24): Pt[] {
  const m = pts.length
  const cum = [0]
  for (let i = 1; i <= m; i++) cum.push(cum[i - 1] + Math.hypot(pts[i % m][0] - pts[i - 1][0], pts[i % m][1] - pts[i - 1][1]))
  const f = noise1(rng, cum[m], wl), g = noise1(rng, cum[m], wl * 0.3)
  const sg = area(pts) >= 0 ? 1 : -1
  return pts.map((p, i) => {
    const a = pts[(i + m - 1) % m], b = pts[(i + 1) % m]
    const tx = b[0] - a[0], ty = b[1] - a[1], l = Math.hypot(tx, ty) || 1
    const off = amp * (f(cum[i]) + 0.3 * g(cum[i]))
    return [p[0] + (ty / l) * off * sg, p[1] - (tx / l) * off * sg]
  })
}

export function offsetPoly(pts: Pt[], d: number, dx = 0, dy = 0): Pt[] {
  const m = pts.length
  const sg = area(pts) > 0 ? 1 : -1
  const nrm = (a: Pt, b: Pt): Pt => {
    const tx = b[0] - a[0], ty = b[1] - a[1], l = Math.hypot(tx, ty) || 1
    return [(ty / l) * sg, (-tx / l) * sg]
  }
  return pts.map((p, i) => {
    const a = pts[(i + m - 1) % m], b = pts[(i + 1) % m]
    const n1 = nrm(a, p), n2 = nrm(p, b)
    let nx = n1[0] + n2[0], ny = n1[1] + n2[1]
    const l = Math.hypot(nx, ny) || 1
    nx /= l
    ny /= l
    const c = Math.max(0.5, nx * n1[0] + ny * n1[1])
    return [p[0] + (nx * d) / c + dx, p[1] + (ny * d) / c + dy]
  })
}

export interface Span {
  row: number
  a: Pt
  b: Pt
  len: number
}

export function scanSpans(poly: Pt[], angle: number, gap: number, rng: Rng, o: { jitter?: number; inset?: number; even?: boolean } = {}): Span[] {
  const { jitter = 0.12, inset = 0, even = true } = o
  const bb = bboxOf(poly)
  const cx = (bb[0] + bb[2]) / 2, cy = (bb[1] + bb[3]) / 2
  const ux = Math.cos(angle), uy = Math.sin(angle)
  const vx = -uy, vy = ux
  let pmin = Infinity, pmax = -Infinity
  for (const [x, y] of poly) {
    const p = (x - cx) * vx + (y - cy) * vy
    if (p < pmin) pmin = p
    if (p > pmax) pmax = p
  }
  const offs: number[] = []
  if (even) {
    let lo = pmin + inset, hi = pmax - inset
    if (hi <= lo) lo = hi = (pmin + pmax) / 2
    const rows = hi > lo ? Math.max(1, Math.round((hi - lo) / gap) + 1) : 1
    const step = rows > 1 ? (hi - lo) / (rows - 1) : 0
    for (let r = 0; r < rows; r++) offs.push(rows > 1 ? lo + r * step + (r > 0 && r < rows - 1 ? (rng() - 0.5) * step * jitter * 2 : 0) : (pmin + pmax) / 2)
  } else {
    let p = pmin + gap * rng.range(0.2, 0.9)
    while (p < pmax) {
      offs.push(p)
      p += gap * (1 + (rng() - 0.5) * 2 * jitter)
    }
  }
  const spans: Span[] = []
  offs.forEach((off, row) => {
    const ox = cx + vx * off, oy = cy + vy * off
    const ts: number[] = []
    for (let i = 0; i < poly.length; i++) {
      const [x0, y0] = poly[i]
      const [x1, y1] = poly[(i + 1) % poly.length]
      const d0 = (x0 - ox) * vx + (y0 - oy) * vy
      const d1 = (x1 - ox) * vx + (y1 - oy) * vy
      if ((d0 <= 0 && d1 > 0) || (d1 <= 0 && d0 > 0)) {
        const t = d0 / (d0 - d1)
        ts.push((x0 + (x1 - x0) * t - ox) * ux + (y0 + (y1 - y0) * t - oy) * uy)
      }
    }
    ts.sort((p, q) => p - q)
    for (let k = 0; k + 1 < ts.length; k += 2) {
      if (ts[k + 1] - ts[k] < 0.8) continue
      spans.push({ row, a: [ox + ux * ts[k], oy + uy * ts[k]], b: [ox + ux * ts[k + 1], oy + uy * ts[k + 1]], len: ts[k + 1] - ts[k] })
    }
  })
  return spans
}

import type { Rng } from '@/lib/ink/rng'

export function noise1(rng: Rng, length: number, wavelength: number): (s: number) => number {
  const n = Math.max(6, Math.ceil(length / wavelength) + 6)
  const k = new Float64Array(n)
  for (let i = 0; i < n; i++) k[i] = rng() * 2 - 1
  const off = rng() * wavelength
  const maxI = n - 3
  return (s) => {
    const u = (s + off) / wavelength
    const fl = Math.floor(u)
    const i = Math.max(1, Math.min(maxI, fl + 1))
    const t = fl + 1 > maxI ? 1 : u - fl
    const p0 = k[i - 1], p1 = k[i], p2 = k[i + 1], p3 = k[i + 2]
    return 0.5 * (2 * p1 + (-p0 + p2) * t + (2 * p0 - 5 * p1 + 4 * p2 - p3) * t * t + (-p0 + 3 * p1 - 3 * p2 + p3) * t * t * t)
  }
}

export function wander(rng: Rng, ...periods: number[]): (x: number) => number {
  const ph = periods.map(() => rng() * Math.PI * 2)
  return (x) => {
    let v = 0
    for (let i = 0; i < periods.length; i++) v += Math.sin((x / periods[i]) * Math.PI * 2 + ph[i]) / (i + 1)
    return v * 0.62
  }
}

export type PaintKey =
  | 'ink' | 'ink-soft' | 'ink-you' | 'pencil' | 'pencil-mark' | 'red' | 'green' | 'marker' | 'hi' | 'focus'
  | 'paper' | 'paper-shade' | 'slip' | 'card' | 'graph' | 'kraft' | 'check' | 'photo' | 'desk' | 'desk-deep'
  | 'rule-blue' | 'rule-red' | 'pad' | 'pad-rule' | 'check-rule'
  | 'ink-muted' | 'pencil-text' | 'orange-text' | 'hi-deep' | 'tape' | 'tape-edge'
  | 'tomato' | 'tangerine' | 'lemon' | 'grass' | 'teal' | 'sky' | 'grape' | 'bubblegum'
  | 'sticky-yellow' | 'sticky-green' | 'sticky-orange' | 'sticky-pink' | 'sticky-blue'
  | 'current'

export const PAINT_KEYS: readonly PaintKey[] = [
  'ink', 'ink-soft', 'ink-you', 'pencil', 'pencil-mark', 'red', 'green', 'marker', 'hi', 'focus',
  'paper', 'paper-shade', 'slip', 'card', 'graph', 'kraft', 'check', 'photo', 'desk', 'desk-deep',
  'rule-blue', 'rule-red', 'pad', 'pad-rule', 'check-rule',
  'ink-muted', 'pencil-text', 'orange-text', 'hi-deep', 'tape', 'tape-edge',
  'tomato', 'tangerine', 'lemon', 'grass', 'teal', 'sky', 'grape', 'bubblegum',
  'sticky-yellow', 'sticky-green', 'sticky-orange', 'sticky-pink', 'sticky-blue',
  'current',
]

const KNOWN = new Set<string>(PAINT_KEYS)

export const BLEND = 'var(--ll-blend)'

export function paint(key: PaintKey): string {
  if (key === 'current') return 'currentColor'
  if (!KNOWN.has(key)) throw new Error(`ink: unknown paint key "${key}"`)
  return `var(--ll-${key})`
}

export type Q = 10 | 20 | 100

export function fmtUnits(k: number, q: Q): string {
  if (k === 0) return '0'
  const neg = k < 0
  const a = neg ? -k : k
  const whole = Math.floor(a / q)
  const frac = a - whole * q
  let s = whole === 0 ? '' : String(whole)
  if (frac !== 0) {
    const digits = q === 10 ? 1 : 2
    const f = String(frac * (10 ** digits / q)).padStart(digits, '0').replace(/0+$/, '')
    s += '.' + f
  }
  return neg ? '-' + s : s
}

export function n(v: number, q: Q = 20): string {
  return Number.isFinite(v) ? fmtUnits(Math.round(v * q), q) : '0'
}

export function esc(s: string): string {
  return s.replace(/[&<>"']/g, (c) => (c === '&' ? '&amp;' : c === '<' ? '&lt;' : c === '>' ? '&gt;' : c === '"' ? '&quot;' : '&#39;'))
}

import type { BBox, Pt, PenName, PenSpec, RibbonLayer, StrokeOpts, StrokeResult } from '@/lib/ink/types'
import type { PaintKey } from '@/lib/ink/paint'
import { clamp, smooth, type Rng } from '@/lib/ink/rng'
import { noise1 } from '@/lib/ink/noise'
import { PathWriter, TAU, TIERS, densify, fillet, resample, smoothClosed, spline, type TierCfg } from '@/lib/ink/geom'
import { pen as resolvePen } from '@/lib/ink/pens'

const wrap = (a: number): number => (a > Math.PI ? a - TAU : a < -Math.PI ? a + TAU : a)

class Sink {
  bb: BBox = [Infinity, Infinity, -Infinity, -Infinity]
  readonly cfg: TierCfg
  constructor(cfg: TierCfg) {
    this.cfg = cfg
  }
  grow(x: number, y: number): void {
    const b = this.bb
    if (x < b[0]) b[0] = x
    if (x > b[2]) b[2] = x
    if (y < b[1]) b[1] = y
    if (y > b[3]) b[3] = y
  }
  poly(pts: Pt[]): string {
    for (const p of pts) this.grow(p[0], p[1])
    return smoothClosed(pts, this.cfg)
  }
}

export function blobPts(cx: number, cy: number, r: number, jag: number, rnd: () => number, nv = 10, sx = 1, sy = 1, rot = 0): Pt[] {
  const pts: Pt[] = []
  const a0 = rnd() * TAU
  for (let i = 0; i < nv; i++) {
    const a = a0 + (i / nv) * TAU
    const rr = r * (1 + jag * (rnd() * 2 - 1))
    const x = Math.cos(a) * rr * sx, y = Math.sin(a) * rr * sy
    pts.push([cx + x * Math.cos(rot) - y * Math.sin(rot), cy + x * Math.sin(rot) + y * Math.cos(rot)])
  }
  return pts
}

interface Geo {
  X: Float64Array; Y: Float64Array; S: Float64Array
  TX: Float64Array; TY: Float64Array; NX: Float64Array; NY: Float64Array
  th: Float64Array; turn: Float64Array; V: Float64Array
  L: number; N: number; seg: number
  nW9: (s: number) => number; nP40: (s: number) => number; nDry: (s: number) => number
  nFlow: (s: number) => number; nDens: (s: number) => number; nTooth: (s: number) => number; nGap: (s: number) => number
  endMode: 'pool' | 'flick' | 'soft'
  startMode: 'pool' | 'soft'
  capN: number
}

function ribbon(g: Geo, lo: Float64Array, ro: Float64Array, a: number, b: number, capS = true, capE = true): Pt[] {
  const { X, Y, NX, NY, TX, TY, capN } = g
  const pts: Pt[] = []
  for (let i = a; i <= b; i++) pts.push([X[i] + NX[i] * lo[i], Y[i] + NY[i] * lo[i]])
  if (capE) {
    const r = (lo[b] + ro[b]) / 2
    for (let k = 1; k <= capN; k++) {
      const ph = (k / (capN + 1)) * Math.PI
      const c = Math.cos(ph), s = Math.sin(ph)
      const w = c >= 0 ? lo[b] : ro[b]
      pts.push([X[b] + NX[b] * w * c + TX[b] * r * s, Y[b] + NY[b] * w * c + TY[b] * r * s])
    }
  }
  for (let i = b; i >= a; i--) pts.push([X[i] - NX[i] * ro[i], Y[i] - NY[i] * ro[i]])
  if (capS) {
    const r = (lo[a] + ro[a]) / 2
    for (let k = 1; k <= capN; k++) {
      const ph = (k / (capN + 1)) * Math.PI
      const c = Math.cos(ph), s = Math.sin(ph)
      const w = c >= 0 ? ro[a] : lo[a]
      pts.push([X[a] - NX[a] * w * c - TX[a] * r * s, Y[a] - NY[a] * w * c - TY[a] * r * s])
    }
  }
  return pts
}

function clampInner(g: Geo, lo: Float64Array, ro: Float64Array): void {
  const { N, seg, turn } = g
  for (let i = 0; i < N; i++) {
    const k = Math.abs(turn[i]) / (4 * seg)
    if (k < 1e-3) continue
    const lim = 0.85 / k
    if (turn[i] > 0) ro[i] = Math.min(ro[i], lim)
    else lo[i] = Math.min(lo[i], lim)
  }
}

function prepare(pts: Pt[], P: PenSpec, rng: Rng, o: StrokeOpts, cfg: TierCfg): Geo {
  let raw = 0
  for (let i = 1; i < pts.length; i++) raw += Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1])
  const step0 = Math.max(P.step * cfg.stepK * (o.simple ? 1.8 : 1), raw / 6000)
  const dense = o.poly ? densify(o.round ? fillet(pts, o.round) : pts, step0) : spline(pts, step0)
  let L0 = 0
  for (let i = 1; i < dense.length; i++) L0 += Math.hypot(dense[i][0] - dense[i - 1][0], dense[i][1] - dense[i - 1][1])
  const step = L0 < 30 ? Math.max(0.7, Math.min(step0, L0 / 22)) : step0
  const { X, Y, S, L } = resample(dense, step)
  const N = X.length
  const rn = rng.fork('noise')
  const nLow = noise1(rn, L, P.wob.wl), nMid = noise1(rn, L, P.wob.wl * 0.3), nTr = noise1(rn, L, 4.5)
  const nW9 = noise1(rn, L, 9), nP40 = noise1(rn, L, 40), nDry = noise1(rn, L, 26), nFlow = noise1(rn, L, 18)
  const r2 = rng.fork('noise2')
  const nDens = noise1(r2, L, 55), nTooth = noise1(r2, L, P.dryWl), nGap = noise1(r2, L, 9)
  const wob = o.raw ? 0 : (o.wobble ?? 1)
  if (wob > 0 && N > 2) {
    const amp = P.wob.amp * wob * clamp(L / 120, 0.2, 1.4)
    const tr = P.wob.tr * wob
    const dx = new Float64Array(N), dy = new Float64Array(N)
    for (let i = 0; i < N; i++) {
      const a = Math.max(0, i - 1), b = Math.min(N - 1, i + 1)
      const tx = X[b] - X[a], ty = Y[b] - Y[a]
      const l = Math.hypot(tx, ty) || 1
      const off = amp * (nLow(S[i]) + 0.3 * nMid(S[i])) + tr * nTr(S[i])
      dx[i] = (ty / l) * off
      dy[i] = (-tx / l) * off
    }
    for (let i = 0; i < N; i++) {
      X[i] += dx[i]
      Y[i] += dy[i]
    }
  }
  const TX = new Float64Array(N), TY = new Float64Array(N), NX = new Float64Array(N), NY = new Float64Array(N)
  const th = new Float64Array(N)
  for (let i = 0; i < N; i++) {
    const a = Math.max(0, i - 1), b = Math.min(N - 1, i + 1)
    const tx = X[b] - X[a], ty = Y[b] - Y[a]
    const l = Math.hypot(tx, ty) || 1
    TX[i] = tx / l
    TY[i] = ty / l
    NX[i] = TY[i]
    NY[i] = -TX[i]
    th[i] = Math.atan2(ty, tx)
  }
  const turn = new Float64Array(N)
  for (let i = 0; i < N; i++) {
    const a = Math.max(0, i - 2), b = Math.min(N - 1, i + 2)
    turn[i] = wrap(th[b] - th[a]) * (4 / Math.max(1, b - a))
  }
  const seg = L / (N - 1) || 1
  const endMode = o.end ?? (rng.fork('end')() < 0.5 ? 'pool' : 'flick')
  const V = new Float64Array(N)
  for (let i = 0; i < N; i++) {
    const vA = Math.min(1, Math.sqrt((S[i] + 0.6) / 9))
    const vD = endMode === 'flick' ? 1 : Math.min(1, Math.sqrt((L - S[i] + 0.6) / 11))
    const vC = 1 / (1 + (Math.abs(turn[i]) / (4 * seg)) * 5)
    V[i] = Math.min(vA, vD, vC)
  }
  for (let pass = 0; pass < 2; pass++) {
    for (let i = 1; i < N; i++) V[i] = Math.min(V[i], V[i - 1] * 0.55 + V[i] * 0.45 + 0.08)
    for (let i = N - 2; i >= 0; i--) V[i] = Math.min(V[i], V[i + 1] * 0.55 + V[i] * 0.45 + 0.08)
  }
  const sp = o.speed ?? 1
  for (let i = 0; i < N; i++) V[i] = clamp(V[i] * sp, 0, 1)
  const startMode = o.start ?? (rng.fork('start')() < 0.8 ? 'pool' : 'soft')
  return { X, Y, S, TX, TY, NX, NY, th, turn, V, L, N, seg, nW9, nP40, nDry, nFlow, nDens, nTooth, nGap, endMode, startMode, capN: o.simple ? 1 : 3 }
}

function runs(cut: Uint8Array | null, N: number): Array<[number, number]> {
  if (!cut) return [[0, N - 1]]
  const out: Array<[number, number]> = []
  let a = -1
  for (let i = 0; i <= N; i++) {
    const c = i === N || cut[i] === 1
    if (!c && a < 0) a = i
    if (c && a >= 0) {
      if (i - 1 - a >= 1) out.push([a, i - 1])
      a = -1
    }
  }
  return out
}

function lineStroke(pts: Pt[], P: PenSpec, rng: Rng, o: StrokeOpts, cfg: TierCfg, lo: boolean): StrokeResult {
  const g = prepare(pts, P, rng, o, cfg)
  const { X, Y, S, L, N, V, turn } = g
  const sink = new Sink(o.simple ? { ...cfg, tol: cfg.tol * 2.2 } : cfg)
  const felt = P.kind === 'felt'
  const W = P.W * (o.width ?? 1)
  const alpha = (o.alpha ?? 1) * P.alpha
  const layers: RibbonLayer[] = []
  const rl = rng.fork('layers')
  const hw = new Float64Array(N)
  const taper = Math.min(L * 0.35, (2.5 + 3.5 * W) * P.taper)
  const dryK = o.dry ?? 1
  const cut = P.gaps > 0 && !o.simple ? new Uint8Array(N) : null
  for (let i = 0; i < N; i++) {
    const toEnd = L - S[i]
    const press = o.press ? o.press(S[i] / L) : 1
    let h: number
    if (felt) {
      h = 0.5 * W * (0.8 + P.swell * (1 - V[i])) * press * (1 + 0.1 * g.nW9(S[i])) * (1 + 0.07 * g.nP40(S[i]))
      h *= 1 + P.dir * Math.sin(g.th[i])
      h *= 1 + 0.08 * P.dens * g.nDens(S[i])
      h *= 1 + 0.16 * Math.exp(-S[i] / 2.5)
      if (g.endMode === 'flick' && toEnd < taper) h *= 0.3 + 0.7 * Math.pow(Math.max(0, toEnd) / taper, 0.75)
      if (P.skip > 0 && V[i] > 0.9) {
        const dry = g.nDry(S[i])
        const t = 1 - 0.55 * P.skip * dryK
        if (dry > t) h *= Math.max(0.42, 1 - (dry - t) * 5)
      }
    } else {
      const pr = 0.86 + 0.18 * g.nP40(S[i]) + 0.1 * (1 - V[i])
      const t0 = Math.min(0.3 * L, 5), t1 = Math.min(0.4 * L, g.endMode === 'flick' ? 9 : 5)
      let e = 1
      if (S[i] < t0) e *= 0.5 + 0.5 * (S[i] / t0)
      if (toEnd < t1) e *= 0.4 + 0.6 * (Math.max(0, toEnd) / t1)
      h = Math.max(0.15, 0.5 * W * e * pr * press * (1 + 0.1 * g.nW9(S[i])))
      h *= 1 + P.dir * Math.sin(g.th[i])
    }
    if (P.dryAmt > 0 && V[i] > 0.55) {
      const d = g.nTooth(S[i])
      if (d > 0.5) h *= 1 - 0.62 * P.dryAmt * dryK * smooth((d - 0.5) / 0.22)
    }
    if (cut && S[i] > 4 && toEnd > 4 && V[i] > 0.8 && g.nGap(S[i]) > 1.05 - 0.6 * P.gaps * dryK) cut[i] = 1
    hw[i] = Math.max(0.12, h)
  }
  if (cut) {
    for (let i = 0; i < N; i++) {
      if (cut[i] !== 1) continue
      let j = i
      while (j < N && cut[j] === 1) j++
      if (j - i < 3) for (let k = i; k < j; k++) cut[k] = 0
      i = j
    }
  }
  const mkLane = (fnL: (i: number) => number, fnR: (i: number) => number = fnL, pieces: Array<[number, number]> = [[0, N - 1]]): string => {
    const l = new Float64Array(N), r = new Float64Array(N)
    for (let i = 0; i < N; i++) {
      l[i] = fnL(i)
      r[i] = fnR(i)
    }
    clampInner(g, l, r)
    let d = ''
    for (const [a, b] of pieces) d += sink.poly(ribbon(g, l, r, a, b, true, true))
    return d
  }
  const color: PaintKey = o.color ?? P.color
  const pieces = runs(cut, N)
  const solid = o.alpha ?? 1
  if (felt) {
    const bleed = P.bleed
    if (P.halo > 0 && !o.simple) {
      const nH1 = noise1(rl, L, 7), nH2 = noise1(rl, L, 7)
      let ja = 0.5, jb = 0.5
      const A = new Float64Array(N), B = new Float64Array(N)
      for (let i = 0; i < N; i++) {
        ja = 0.5 * ja + 0.5 * rl()
        jb = 0.5 * jb + 0.5 * rl()
        const soak = 0.4 * (1 - V[i])
        A[i] = hw[i] + bleed * (0.4 + 0.85 * Math.max(0, nH1(S[i])) + 0.4 * ja + soak)
        B[i] = hw[i] + bleed * (0.4 + 0.85 * Math.max(0, nH2(S[i])) + 0.4 * jb + soak)
      }
      layers.push({ k: 'halo', d: mkLane((i) => A[i], (i) => B[i]), fill: color, op: P.halo * (lo ? 0.85 : 0.55) })
      if (!lo) {
        let jc = 0.5
        const C = new Float64Array(N)
        for (let i = 0; i < N; i++) {
          jc = 0.4 * jc + 0.6 * rl()
          C[i] = hw[i] + bleed * (0.25 + 0.55 * jc)
        }
        layers.push({ k: 'halo', d: mkLane((i) => C[i]), fill: color, op: P.halo })
        const cnt = Math.floor((L / 3.2) * P.feather * (0.6 + 0.8 * rl()))
        const hp = new PathWriter(cfg.q)
        for (let c = 0; c < cnt; c++) {
          const i = 1 + Math.floor(rl() * (N - 2))
          const side = rl() < 0.5 ? 1 : -1
          const ang = (rl() - 0.5) * 2.2
          const nx = g.NX[i] * side, ny = g.NY[i] * side
          const dx = nx * Math.cos(ang) - ny * Math.sin(ang), dy = nx * Math.sin(ang) + ny * Math.cos(ang)
          const len = hw[i] + bleed * (0.5 + rl() * rl() * 1.8)
          const bx = X[i] + nx * hw[i] * 0.5, by = Y[i] + ny * hw[i] * 0.5
          const bw = 0.22 + 0.3 * rl()
          const tx = g.TX[i] * bw, ty = g.TY[i] * bw
          const tip: Pt = [X[i] + dx * len, Y[i] + dy * len]
          sink.grow(tip[0], tip[1])
          hp.M(bx + tx, by + ty).L(tip[0], tip[1]).L(bx - tx, by - ty).Z()
        }
        if (hp.d) layers.push({ k: 'hair', d: hp.d, fill: color, op: Math.min(1, P.halo * 1.6) })
      }
    }
    const jit = new Float64Array(N)
    for (let i = 0; i < N; i++) jit[i] = lo ? 1 : 1 + 0.07 * (rl() - 0.5)
    layers.push({ k: 'body', d: mkLane((i) => hw[i] * jit[i], (i) => hw[i] * jit[N - 1 - i], pieces), fill: color, op: alpha })
    if (!o.simple) {
      const core = new Float64Array(N)
      let any = false
      for (let i = 0; i < N; i++) {
        const dn = 1 + 0.6 * P.dens * g.nDens(S[i] + 17)
        core[i] = cut && cut[i] ? 0 : 0.72 * hw[i] * Math.max(Math.pow(1 - V[i], 1.2), 0.8 * (0.5 + 0.5 * g.nFlow(S[i])) - 0.1) * dn
        if (core[i] > 0.18) any = true
        else core[i] = 0
      }
      let cd = any ? mkLane((i) => core[i]) : ''
      let pd = ''
      let hd2 = ''
      const pool = (i: number, k: number, jag: number): void => {
        const r = hw[i] * k * P.pool
        pd += sink.poly(blobPts(X[i], Y[i], r, jag, rl, 11))
        if (P.halo > 0 && !lo) hd2 += sink.poly(blobPts(X[i], Y[i], r + bleed * 1.5, 0.2, rl, 12))
      }
      if (g.startMode === 'pool') pool(0, 1.05 + 0.25 * rl(), 0.14)
      if (g.endMode === 'pool') pool(N - 1, 0.95 + 0.3 * rl(), 0.14)
      let lastPool = -9
      for (let i = 2; i < N - 2; i++) {
        if (Math.abs(turn[i]) > 1.35 && i - lastPool > 4) {
          pool(i, 0.6 + 0.25 * Math.min(1, Math.abs(turn[i]) - 1.35), 0.14)
          lastPool = i
        }
      }
      if (lo) {
        cd += pd
        pd = ''
      }
      if (cd) layers.push({ k: 'core', d: cd, fill: color, op: P.core * solid })
      if (hd2) layers.push({ k: 'halo', d: hd2, fill: color, op: P.halo * 0.9 })
      if (pd) layers.push({ k: 'pool', d: pd, fill: color, op: Math.min(1, P.core * 1.1) * solid })
    }
  } else {
    if (!o.simple) layers.push({ k: 'smear', d: mkLane((i) => hw[i] * 1.2), fill: color, op: P.smear * solid })
    layers.push({ k: 'body', d: mkLane((i) => hw[i] * (1 + 0.12 * (lo ? 0 : rl() - 0.5)), (i) => hw[i] * (1 + 0.12 * (lo ? 0 : rl() - 0.5)), pieces), fill: color, op: alpha })
    if (!o.simple) {
      const nc = noise1(rl, L, 40)
      layers.push({ k: 'core', d: mkLane((i) => (hw[i] > 0.3 ? hw[i] * 0.55 * (0.7 + 0.3 * nc(S[i] + 13)) * (1 + 0.4 * P.dens * g.nDens(S[i] + 5)) : 0)), fill: color, op: alpha * 0.55 })
    }
  }
  return { kind: P.kind, layers, bbox: sink.bb, len: L, end: [X[N - 1], Y[N - 1]], start: [X[0], Y[0]] }
}

function markerStroke(pts: Pt[], P: PenSpec, rng: Rng, o: StrokeOpts, cfg: TierCfg, lo: boolean): StrokeResult {
  const g = prepare(pts, P, rng, { ...o, start: o.start ?? 'pool' }, cfg)
  const { X, Y, S, L, N } = g
  const sink = new Sink(cfg)
  const W = P.W * (o.width ?? 1)
  const alpha = (o.alpha ?? 1) * P.alpha
  const rl = rng.fork('layers')
  const hl = P.kind === 'hl'
  const color: PaintKey = o.color ?? P.color
  const hwA = new Float64Array(N)
  const nM = noise1(rl, L, 14), nE = noise1(rl, L, 3.5), nE2 = noise1(rl, L, 3.5)
  const taper = Math.min(0.25 * L, 0.5 * W)
  const cutLen = Math.min(W * P.cutK, L * 0.4)
  const slantA = rl() < 0.5 ? 1 : -1
  const lo_ = new Float64Array(N), ro_ = new Float64Array(N)
  for (let i = 0; i < N; i++) {
    const ang = Math.atan2(g.TY[i], g.TX[i])
    const chisel = hl ? 0.8 + 0.2 * Math.abs(Math.sin(ang - P.nib)) : 0.5 + 0.5 * Math.abs(Math.sin(ang - P.nib))
    let hw = 0.5 * W * chisel * (o.press ? o.press(S[i] / L) : 1) * (1 + 0.06 * nM(S[i]))
    if (g.endMode === 'flick' && L - S[i] < taper) hw *= 0.6 + 0.4 * ((L - S[i]) / taper)
    hwA[i] = hw
    let a = hw * (1 + 0.35 * P.edge * nE(S[i]) * 0.5)
    let b = hw * (1 + 0.35 * P.edge * nE2(S[i]) * 0.5)
    if (S[i] < cutLen) {
      const c = 1 - 0.6 * (1 - S[i] / cutLen)
      if (slantA > 0) a *= c
      else b *= c
    }
    if (L - S[i] < cutLen) {
      const c = 1 - 0.6 * (1 - (L - S[i]) / cutLen)
      if (slantA > 0) b *= c
      else a *= c
    }
    lo_[i] = a
    ro_[i] = b
  }
  const layers: RibbonLayer[] = []
  const lane = (l2: (i: number) => number, r2: (i: number) => number): string => {
    const a = new Float64Array(N), b = new Float64Array(N)
    for (let i = 0; i < N; i++) {
      a[i] = l2(i)
      b[i] = r2(i)
    }
    clampInner(g, a, b)
    return sink.poly(ribbon(g, a, b, 0, N - 1, false, false))
  }
  layers.push({ k: 'halo', d: lane((i) => lo_[i] + P.bleed * (0.5 + 0.5 * nE(S[i] + 9)), (i) => ro_[i] + P.bleed * (0.5 + 0.5 * nE2(S[i] + 9))), fill: color, op: alpha * P.wet })
  let body = lane((i) => lo_[i], (i) => ro_[i])
  const rw1 = hl ? 0.55 : 0.8
  const rim = lane((i) => lo_[i], (i) => -lo_[i] + rw1 * (0.6 + 0.8 * rl())) + lane((i) => -ro_[i] + rw1 * (0.6 + 0.8 * rl()), (i) => ro_[i])
  let rule: 'evenodd' | undefined
  const extra: RibbonLayer[] = []
  if (!hl && !lo && L > 6) {
    const nS = noise1(rl, L, 30)
    for (let s = 0; s < 2; s++) {
      const base = (rl() - 0.5) * 0.9
      const off = (i: number): number => hwA[i] * (base + 0.25 * nS(S[i] + s * 40))
      extra.push({ k: 'streak', d: lane((i) => Math.max(0.1, 0.3 + off(i)), (i) => Math.max(0.1, 0.3 - off(i))), fill: color, op: P.edge * 0.5 })
    }
    const nGap = noise1(rl, L, 11)
    let sd = ''
    let inSlit = false, sIdx = 0
    for (let i = 0; i < N; i++) {
      const dry = Math.max(0, nGap(S[i] + 31) - (g.V[i] > 0.8 ? 0.3 : 0.5))
      if (dry > 0.3 && !inSlit) { inSlit = true; sIdx = i }
      if ((dry <= 0.3 || i === N - 1) && inSlit) {
        inSlit = false
        if (i - sIdx > 4) {
          const off = hwA[sIdx] * (rl() - 0.5) * 0.7
          const top: Pt[] = [], bot: Pt[] = []
          for (let j = sIdx; j < i; j++) {
            const tt = (j - sIdx) / (i - sIdx)
            const wdt = 0.28 * Math.sin(Math.PI * tt)
            top.push([X[j] + g.NX[j] * (off + wdt), Y[j] + g.NY[j] * (off + wdt)])
            bot.unshift([X[j] + g.NX[j] * (off - wdt), Y[j] + g.NY[j] * (off - wdt)])
          }
          sd += smoothClosed([...top, ...bot], cfg)
        }
      }
    }
    if (sd) {
      body += sd
      rule = 'evenodd'
    }
  }
  layers.push({ k: 'body', d: body, fill: color, op: alpha, rule })
  layers.push({ k: 'rim', d: rim, fill: color, op: P.edge })
  layers.push(...extra)
  return { kind: P.kind, layers, bbox: sink.bb, len: L, end: [X[N - 1], Y[N - 1]], start: [X[0], Y[0]] }
}

export function stroke(pointsIn: Pt[], penIn: PenName | PenSpec, rng: Rng, o: StrokeOpts = {}): StrokeResult {
  const P = resolvePen(penIn)
  const tier = o.tier ?? 'lo'
  const cfg = TIERS[tier]
  const pts = pointsIn.filter((p) => Number.isFinite(p[0]) && Number.isFinite(p[1])).map((p): Pt => [clamp(p[0], -1e5, 1e5), clamp(p[1], -1e5, 1e5)])
  if (pts.length === 0) return { kind: P.kind, layers: [], bbox: [0, 0, 0, 0], len: 0, start: [0, 0], end: [0, 0] }
  if (pts.length < 2) return dot(pts[0][0], pts[0][1], P.W * 0.6, P, rng, o)
  return P.kind === 'marker' || P.kind === 'hl' ? markerStroke(pts, P, rng, o, cfg, tier === 'lo') : lineStroke(pts, P, rng, o, cfg, tier === 'lo')
}

export function dot(cx: number, cy: number, r: number, penIn: PenName | PenSpec, rng: Rng, o: StrokeOpts = {}): StrokeResult {
  const P = resolvePen(penIn)
  const tier = o.tier ?? 'lo'
  const cfg = TIERS[tier]
  const sink = new Sink(cfg)
  const rl = rng.fork('dot')
  const color: PaintKey = o.color ?? P.color
  const layers: RibbonLayer[] = []
  const rr = r * (o.width ?? 1)
  if (P.kind === 'felt') {
    if (P.halo > 0 && tier === 'hi') layers.push({ k: 'halo', d: sink.poly(blobPts(cx, cy, rr + P.bleed * 1.4, 0.2, rl, 12)), fill: color, op: P.halo * 0.9 })
    layers.push({ k: 'body', d: sink.poly(blobPts(cx, cy, rr, 0.09, rl, 11)), fill: color, op: P.alpha * (o.alpha ?? 1) })
    layers.push({ k: 'pool', d: sink.poly(blobPts(cx + rr * 0.05, cy, rr * 0.7, 0.1, rl, 9)), fill: color, op: P.core })
  } else {
    if (tier === 'hi') layers.push({ k: 'smear', d: sink.poly(blobPts(cx, cy, rr * 1.15, 0.1, rl, 10)), fill: color, op: P.smear || 0.2 })
    layers.push({ k: 'body', d: sink.poly(blobPts(cx, cy, rr, 0.12, rl, 10)), fill: color, op: P.alpha * (o.alpha ?? 1) })
  }
  return { kind: P.kind === 'hl' || P.kind === 'marker' ? 'felt' : P.kind, layers, bbox: sink.bb, len: 0, end: [cx, cy], start: [cx, cy] }
}

import type { PaintKey } from '@/lib/ink/paint'
import type { Accent, BasePenName, PenName, PenSpec } from '@/lib/ink/types'

const BASE: PenSpec = {
  kind: 'felt', color: 'ink', grain: 'felt', cls: 'std',
  W: 1.7, alpha: 0.92,
  wob: { amp: 0.8, wl: 80, tr: 0.16 }, step: 1.8,
  halo: 0, bleed: 1, core: 0.3, pool: 1, feather: 0, skip: 0, swell: 0.4, dir: 0,
  dryAmt: 0, dryWl: 7, gaps: 0, dens: 0.5, taper: 1,
  smear: 0, waxy: false,
  nib: 0, edge: 0.2, wet: 0.2, cutK: 0.22,
}

const felt = (color: PaintKey, o: Partial<PenSpec> = {}): PenSpec => ({
  ...BASE, kind: 'felt', grain: 'felt', color,
  halo: 0.14, bleed: 1.05, core: 0.36, pool: 1, feather: 0.5, skip: 0.3, swell: 0.4, dir: 0.06, dens: 0.5, ...o,
})

const pencil = (color: PaintKey, o: Partial<PenSpec> = {}): PenSpec => ({
  ...BASE, kind: 'pencil', grain: o.waxy ? 'waxy' : 'graphite', color,
  W: 1.5, alpha: 0.95, wob: { amp: 0.6, wl: 110, tr: 0.12 }, step: 1.3, smear: 0.22, dens: 0.5, ...o,
})

const marker = (color: PaintKey, o: Partial<PenSpec> = {}): PenSpec => ({
  ...BASE, kind: 'marker', grain: 'marker', color,
  W: 9, alpha: 0.62, nib: -0.75, edge: 0.3, wet: 0.22, bleed: 1, wob: { amp: 0.9, wl: 90, tr: 0.1 }, step: 2.2, cutK: 0.22, ...o,
})

const FELTS: Record<'ink' | 'blue' | 'redfelt' | 'greenfelt' | 'focus', PenSpec> = {
  ink: felt('ink'),
  blue: felt('ink-you', { W: 1.85, alpha: 0.9, wob: { amp: 0.9, wl: 70, tr: 0.18 }, halo: 0.16, bleed: 1.2, core: 0.32, pool: 1.1, feather: 0.6, skip: 0.25 }),
  redfelt: felt('red', { W: 1.75, alpha: 0.9, halo: 0.14, bleed: 1, core: 0.32 }),
  greenfelt: felt('green', { W: 1.75, alpha: 0.9, halo: 0.14, bleed: 1, core: 0.32 }),
  focus: felt('focus', { W: 2.2, alpha: 0.95, wob: { amp: 0.9, wl: 70, tr: 0.16 }, halo: 0.16, bleed: 1.2, core: 0.3, skip: 0.15 }),
}

const PENCILS: Record<'pencil' | 'red' | 'green' | 'orange' | 'bluepencil', PenSpec> = {
  pencil: pencil('pencil'),
  red: pencil('red', { alpha: 0.9, smear: 0.26, waxy: true }),
  green: pencil('green', { alpha: 0.9, smear: 0.26, waxy: true }),
  orange: pencil('tangerine', { alpha: 0.9, smear: 0.28, waxy: true }),
  bluepencil: pencil('ink-you', { W: 1.4, alpha: 0.88, smear: 0.26, waxy: true }),
}

function withClass(p: PenSpec, cls: 'fine' | 'brush'): PenSpec {
  if (p.kind === 'felt') {
    return cls === 'fine'
      ? { ...p, cls, W: p.W * 0.68, alpha: Math.min(0.96, p.alpha + 0.02), wob: { amp: p.wob.amp * 0.7, wl: p.wob.wl * 1.2, tr: p.wob.tr * 0.6 }, step: 1.6, halo: p.halo * 0.55, bleed: p.bleed * 0.6, core: p.core * 0.8, pool: p.pool * 0.7, feather: p.feather * 0.4, skip: p.skip * 0.4, swell: 0.18, dir: 0, dens: 0.3 }
      : { ...p, cls, W: p.W * 2, alpha: p.alpha - 0.02, wob: { amp: p.wob.amp * 1.1, wl: p.wob.wl * 1.1, tr: p.wob.tr * 0.75 }, step: 2.2, halo: p.halo * 0.85, bleed: p.bleed * 1.2, core: p.core * 1.1, pool: p.pool * 1.15, feather: p.feather * 1.1, skip: 0.15, swell: 0.8, dir: 0.38, dryAmt: 0.55, dryWl: 7, gaps: 0.5, dens: 0.8, taper: 1.6 }
  }
  return cls === 'fine'
    ? { ...p, cls, W: p.W * 0.68, alpha: p.alpha * 0.92, smear: p.smear * 0.8, wob: { ...p.wob, amp: p.wob.amp * 0.8 }, step: 1.1 }
    : { ...p, cls, W: p.W * 1.9, alpha: p.alpha * 0.88, smear: p.smear * 1.4, dir: 0.14, dryAmt: 0.25, step: 1.6 }
}

const ACCENTS: readonly Accent[] = ['tomato', 'tangerine', 'lemon', 'grass', 'teal', 'sky', 'grape', 'bubblegum']

function build(): Record<PenName, PenSpec> {
  const out = {} as Record<PenName, PenSpec>
  const base: Record<BasePenName, PenSpec> = { ...FELTS, ...PENCILS }
  for (const k of Object.keys(base) as BasePenName[]) {
    out[k] = base[k]
    out[`${k}.fine`] = withClass(base[k], 'fine')
    out[`${k}.brush`] = withClass(base[k], 'brush')
  }
  out.terracotta = marker('marker')
  out.hi = marker('hi', { kind: 'hl', W: 14, alpha: 0.52, nib: 1.45, edge: 0.14, wet: 0.2, bleed: 0.6, wob: { amp: 0.5, wl: 160, tr: 0.05 }, step: 2.4, cutK: 0.28 })
  for (const c of ACCENTS) {
    out[`m_${c}`] = marker(c)
    out[`f_${c}`] = felt(c)
  }
  return out
}

export const PENS: Readonly<Record<PenName, PenSpec>> = build()

export function pen(p: PenName | PenSpec, over?: Partial<PenSpec>): PenSpec {
  const base = typeof p === 'string' ? PENS[p] : p
  if (!base) throw new Error(`ink: unknown pen "${String(p)}"`)
  return over ? { ...base, ...over, wob: { ...base.wob, ...over.wob } } : base
}

import type { Knobs } from '@/lib/ink/builder'
import type { Tier } from '@/lib/ink/types'
import {
  bucketBox, knobsKey, orderLayers, runCounter, runRecipe, stableStringify,
  type Box, type Density, type Dir, type InkLayerName, type RawFrame, type Recipe,
} from '@/lib/ink/recipes'

export interface FrameRequest<P> {
  box: Box
  params: P
  seed: string
  tier: Tier
  density: Density
  dir: Dir
  knobs: Knobs
  pad?: number
  lazy?: readonly InkLayerName[]
  paramsKey?: string
}

export interface Frame {
  key: string
  parts: Partial<Record<InkLayerName, string>>
  layers: InkLayerName[]
  pad: number
  w: number
  h: number
  chars: number
}

interface Entry {
  raw: RawFrame
  lazy: Partial<Record<InkLayerName, string>>
  chars: number
}

class InkCache {
  private map = new Map<string, Entry>()
  private max = 600
  private maxChars = 6_000_000
  private chars = 0
  hits = 0
  misses = 0

  get(key: string): Entry | undefined {
    const e = this.map.get(key)
    if (e) {
      this.map.delete(key)
      this.map.set(key, e)
    }
    return e
  }

  set(key: string, e: Entry): void {
    const old = this.map.get(key)
    if (old) this.chars -= old.chars
    this.map.delete(key)
    this.map.set(key, e)
    this.chars += e.chars
    this.evict()
  }

  grow(e: Entry, chars: number): void {
    e.chars += chars
    this.chars += chars
    this.evict()
  }

  private evict(): void {
    for (const k of this.map.keys()) {
      if (this.map.size <= 1 || (this.map.size <= this.max && this.chars <= this.maxChars)) break
      const e = this.map.get(k)
      if (e) this.chars -= e.chars
      this.map.delete(k)
    }
  }

  resize(o: { max?: number; maxChars?: number }): void {
    if (o.max !== undefined) this.max = Math.max(1, o.max)
    if (o.maxChars !== undefined) this.maxChars = Math.max(1, o.maxChars)
    this.evict()
  }

  clear(): void {
    this.map.clear()
    this.chars = 0
  }

  stats(): { hits: number; misses: number; runs: number; size: number; chars: number } {
    return { hits: this.hits, misses: this.misses, runs: runCounter.runs, size: this.map.size, chars: this.chars }
  }
}

export const inkCache = new InkCache()

const sum = (parts: Partial<Record<string, string>>): number => {
  let c = 0
  for (const k in parts) c += parts[k]?.length ?? 0
  return c
}

export function frameKey<P>(recipe: Recipe<P>, req: FrameRequest<P>): string {
  const b = bucketBox(req.box.w, req.box.h)
  const tier = req.density === 'calm' ? 'lo' : req.tier
  return [`${recipe.id}@${recipe.rev}`, `${b.w}x${b.h}`, req.seed, tier, req.density, req.dir, req.pad ?? '', req.paramsKey ?? stableStringify(req.params), knobsKey(req.knobs)].join('|')
}

export function inkFrame<P>(recipe: Recipe<P>, req: FrameRequest<P>): Frame {
  const key = frameKey(recipe, req)
  const box = bucketBox(req.box.w, req.box.h)
  const want = (req.lazy ?? []).filter((l) => recipe.lazy.includes(l))
  const run = (lazy: readonly InkLayerName[], lazyOnly: boolean): RawFrame => runRecipe(recipe, { ...req, box, lazy, lazyOnly })
  let entry = inkCache.get(key)
  if (entry) inkCache.hits++
  else {
    inkCache.misses++
    const raw = run(want, false)
    const lazy: Entry['lazy'] = {}
    const parts: RawFrame['parts'] = {}
    for (const k of raw.layers) {
      if (raw.lazyLayers.includes(k)) lazy[k] = raw.parts[k]
      else parts[k] = raw.parts[k]
    }
    for (const l of want) lazy[l] ??= ''
    entry = { raw: { ...raw, parts, layers: orderLayers(Object.keys(parts) as InkLayerName[]) }, lazy, chars: sum(parts) + sum(lazy) }
    inkCache.set(key, entry)
  }
  const missing = want.filter((l) => entry.lazy[l] === undefined)
  if (missing.length) {
    const raw = run(missing, true)
    for (const l of missing) entry.lazy[l] = raw.parts[l] ?? ''
    inkCache.grow(entry, sum(raw.parts))
  }
  const parts: Frame['parts'] = { ...entry.raw.parts }
  for (const l of want) if (entry.lazy[l]) parts[l] = entry.lazy[l]
  return { key, parts, layers: orderLayers(Object.keys(parts) as InkLayerName[]), pad: entry.raw.pad, w: box.w, h: box.h, chars: sum(parts) }
}

export function frameSvg(frame: Pick<Frame, 'parts' | 'layers'>, layers?: readonly InkLayerName[], wrap = true): string {
  let out = ''
  for (const k of frame.layers) {
    if (layers && !layers.includes(k)) continue
    out += wrap ? `<g data-layer="${k}">${frame.parts[k]}</g>` : frame.parts[k]
  }
  return out
}

