const wrapperStyle: React.CSSProperties = { display: "contents" }

const num = (cs: CSSStyleDeclaration, name: string, fallback: number): number => {
  const v = Number.parseFloat(cs.getPropertyValue(name))
  return Number.isFinite(v) ? v : fallback
}

function readKnobs(el: Element): Knobs {
  const cs = getComputedStyle(el)
  return {
    wobble: num(cs, "--ll-wobble", 1),
    misreg: num(cs, "--ll-misreg-k", 1),
    bleed: num(cs, "--ll-bleed", 6) / 6,
    width: num(cs, "--ll-stroke-fine", 1.7) / 1.7,
  }
}

const sameKnobs = (a: Knobs, b: Knobs) => a.wobble === b.wobble && a.misreg === b.misreg && a.bleed === b.bleed && a.width === b.width

const ATTRS = ["data-theme", "data-density", "data-motion", "dir"]

export function InkProvider({ tier = "lo", density: densityProp, motion = "system", theme, dir: dirProp, knobs: knobsProp, textures = false, defs = true, patterns, children }: InkProviderProps) {
  const ref = React.useRef<HTMLDivElement>(null)
  const [css, setCss] = React.useState<Knobs>(DEFAULT_KNOBS)
  const [inheritedDensity, setInheritedDensity] = React.useState<Density>("comfortable")
  const [inheritedDir, setInheritedDir] = React.useState<Dir>("ltr")

  React.useLayoutEffect(() => {
    const el = ref.current
    if (!el) return
    const read = () => {
      const k = readKnobs(el)
      setCss((prev) => (sameKnobs(prev, k) ? prev : k))
      const d = el.parentElement?.closest("[data-density]")?.getAttribute("data-density")
      setInheritedDensity(d === "compact" || d === "calm" ? d : "comfortable")
      const r = el.parentElement?.closest("[dir]")?.getAttribute("dir") ?? el.ownerDocument.documentElement.getAttribute("dir")
      setInheritedDir(r === "rtl" ? "rtl" : "ltr")
    }
    read()
    if (typeof MutationObserver === "undefined") return
    const mo = new MutationObserver(read)
    mo.observe(el, { attributes: true, attributeFilter: ATTRS })
    mo.observe(el.ownerDocument.documentElement, { attributes: true, attributeFilter: ATTRS })
    return () => mo.disconnect()
  }, [theme, densityProp, motion])

  const density = densityProp ?? inheritedDensity
  const dir = dirProp ?? inheritedDir
  const outerScope = React.useContext(InkContext).scope
  const scope = React.useMemo<InkScopeProps>(() => {
    const own: InkScopeProps = {}
    if (densityProp) own["data-density"] = densityProp
    if (motion === "reduced") own["data-motion"] = "reduced"
    if (theme) own["data-theme"] = theme
    return { ...outerScope, ...own }
  }, [outerScope, densityProp, motion, theme])
  const knobsPropKey = knobsProp ? stableStringify(knobsProp) : ""
  const knobs = React.useMemo(
    () => resolveKnobs(knobsProp ? { ...css, ...knobsProp } : css, density),
    [css, density, knobsPropKey],
  )
  const value = React.useMemo<InkContextValue>(() => ({ tier, density, dir, motion, knobs, hasProvider: true, scope }), [tier, density, dir, motion, knobs, scope])

  return (
    <InkContext.Provider value={value}>
      <div ref={ref} data-ll-scope="" data-density={densityProp} data-motion={motion === "reduced" ? "reduced" : undefined} data-theme={theme} style={wrapperStyle}>
        {defs ? <InkDefs patterns={patterns} /> : null}
        {textures ? <InkTiles tiles={textures} /> : null}
        {children}
      </div>
    </InkContext.Provider>
  )
}

import * as React from "react"

import { inkViewBox } from "@/lib/ink/builder"
import type { Frame } from "@/lib/ink/react/cache"

export function InkSvg({ kind, frame, still, ref }: { kind: string; frame: Frame | null; still?: boolean; ref?: React.Ref<SVGSVGElement> }) {
  const pad = frame?.pad ?? 0
  return (
    <svg
      ref={ref}
      data-ink={kind}
      data-still={still ? "" : undefined}
      aria-hidden="true"
      focusable="false"
      className="pointer-events-none absolute"
      viewBox={frame ? inkViewBox(frame) : undefined}
      preserveAspectRatio="none"
      style={{
        position: "absolute",
        pointerEvents: "none",
        left: -pad,
        top: -pad,
        width: `calc(100% + ${2 * pad}px)`,
        height: `calc(100% + ${2 * pad}px)`,
        overflow: "visible",
        zIndex: -1,
      }}
    >
      {frame?.layers.map((name) => (
        <g key={name} data-layer={name} suppressHydrationWarning dangerouslySetInnerHTML={{ __html: frame.parts[name] ?? "" }} />
      ))}
    </svg>
  )
}

import { Ink, type InkOptions, type Knobs } from '@/lib/ink/builder'
import type { LayerName, Tier } from '@/lib/ink/types'

export type InkLayerName = LayerName | 'indeterminate' | 'open' | 'busy'
export type Density = 'comfortable' | 'compact' | 'calm'
export type Dir = 'ltr' | 'rtl'

export interface Box {
  w: number
  h: number
}

export const INK_LAYER_ORDER: readonly InkLayerName[] = [
  'rest', 'disabled', 'invalid', 'checked', 'indeterminate', 'open', 'busy', 'hover', 'pressed', 'focus',
]

export function orderLayers<T extends string>(names: readonly T[]): T[] {
  const rank = (k: string) => {
    const i = INK_LAYER_ORDER.indexOf(k as InkLayerName)
    return i < 0 ? INK_LAYER_ORDER.length : i
  }
  return [...names].sort((a, b) => rank(a) - rank(b))
}

export interface RecipeContext {
  readonly tier: Tier
  readonly density: Density
  readonly calm: boolean
  readonly knobs: Knobs
  readonly dir: Dir
  readonly seed: string
  wants(layer: InkLayerName): boolean
  lazy(layer: InkLayerName, fn: (ink: Ink) => void): void
  readonly lazyOnly: boolean
}

export interface RecipeDef<P> {
  id: string
  kind?: string
  layers: readonly InkLayerName[]
  lazy?: readonly InkLayerName[]
  pad: number | ((box: Box, params: P, ctx: RecipeContext) => number)
  draw(ink: Ink, box: Box, params: P, ctx: RecipeContext): void
}

export interface Recipe<P = unknown> extends RecipeDef<P> {
  readonly lazy: readonly InkLayerName[]
  readonly kind: string
  readonly isInkRecipe: true
  readonly rev: number
}

const ID_RE = /^[a-z][a-z0-9]*(-[a-z0-9]+)*$/
const registry = new Map<string, Recipe<never>>()

export function defineRecipe<P = Record<string, never>>(def: RecipeDef<P>): Recipe<P> {
  if (!ID_RE.test(def.id)) throw new Error(`ink recipe id "${def.id}" must be kebab-case (letters, digits, hyphens)`)
  const lazy = def.lazy ?? []
  for (const l of lazy) if (!def.layers.includes(l)) throw new Error(`ink recipe "${def.id}": lazy layer "${l}" is not in layers`)
  const recipe: Recipe<P> = { ...def, lazy, kind: def.kind ?? def.id, isInkRecipe: true, rev: (registry.get(def.id)?.rev ?? 0) + 1 }
  registry.set(def.id, recipe as unknown as Recipe<never>)
  return recipe
}

export function getRecipe(id: string): Recipe<never> | undefined {
  return registry.get(id)
}

export function allRecipes(): Recipe<never>[] {
  return [...registry.values()]
}

export const DEFAULT_KNOBS: Knobs = { wobble: 1, misreg: 1, bleed: 1, width: 1 }

export function resolveKnobs(themeKnobs: Knobs, density: Density): Knobs {
  if (density === 'calm') return { ...DEFAULT_KNOBS, bleed: themeKnobs.bleed }
  if (density === 'compact') return { ...themeKnobs, misreg: themeKnobs.misreg * 0.85, width: themeKnobs.width * 0.94 }
  return themeKnobs
}

export interface RunRequest<P> {
  box: Box
  params: P
  seed: string
  tier: Tier
  density: Density
  dir: Dir
  knobs: Knobs
  pad?: number
  lazy?: readonly InkLayerName[]
  lazyOnly?: boolean
}

export interface RawFrame {
  parts: Partial<Record<InkLayerName, string>>
  layers: InkLayerName[]
  lazyLayers: InkLayerName[]
  pad: number
  w: number
  h: number
}

export const runCounter = { runs: 0 }

export function runRecipe<P>(recipe: Recipe<P>, req: RunRequest<P>): RawFrame {
  const { box, params } = req
  const calm = req.density === 'calm'
  const tier: Tier = calm ? 'lo' : req.tier
  const wanted = new Set<InkLayerName>(req.lazy ?? [])
  const inkOpts: InkOptions = { tier, calm, knobs: req.knobs }
  const seed = `${req.seed}|${recipe.id}`
  const lazyOnly = req.lazyOnly === true
  const ctxBase = { tier, density: req.density, calm, knobs: req.knobs, dir: req.dir, seed, lazyOnly }
  const lazyParts: Partial<Record<InkLayerName, string>> = {}
  const pad0 = req.pad ?? (typeof recipe.pad === 'number' ? recipe.pad : undefined)
  const ctx: RecipeContext = {
    ...ctxBase,
    wants: (layer) => wanted.has(layer),
    lazy(layer, fn) {
      if (!wanted.has(layer)) return
      const li = new Ink(`${seed}|${layer}`, inkOpts)
      li.layer(layer as LayerName, () => fn(li))
      lazyParts[layer] = li.toSvg({ w: box.w, h: box.h, pad: pad0 ?? 12 }).parts[layer as LayerName] ?? ''
    },
  }
  const ink = new Ink(seed, inkOpts)
  runCounter.runs++
  recipe.draw(ink, box, params, ctx)
  const pad = req.pad ?? (typeof recipe.pad === 'number' ? recipe.pad : recipe.pad(box, params, ctx))
  const parts: Partial<Record<InkLayerName, string>> = {}
  if (!lazyOnly) {
    const res = ink.toSvg({ w: box.w, h: box.h, pad })
    for (const k of res.layers) {
      const markup = res.parts[k]
      if (markup) parts[k as InkLayerName] = markup
    }
  }
  const lazyLayers: InkLayerName[] = []
  for (const k of Object.keys(lazyParts) as InkLayerName[]) {
    if (lazyParts[k]) {
      parts[k] = lazyParts[k]
      lazyLayers.push(k)
    }
  }
  return { parts, layers: orderLayers(Object.keys(parts) as InkLayerName[]), lazyLayers: orderLayers(lazyLayers), pad, w: box.w, h: box.h }
}

let warnedFn = false

export function stableStringify(v: unknown): string {
  if (v === null || typeof v === 'boolean' || typeof v === 'string') return JSON.stringify(v)
  if (typeof v === 'number') return Number.isFinite(v) ? String(v) : '"NaN"'
  if (v === undefined) return 'null'
  if (Array.isArray(v)) return `[${v.map(stableStringify).join(',')}]`
  if (typeof v === 'object') {
    const o = v as Record<string, unknown>
    const keys = Object.keys(o).filter((k) => o[k] !== undefined).sort()
    return `{${keys.map((k) => `${JSON.stringify(k)}:${stableStringify(o[k])}`).join(',')}}`
  }
  if (!warnedFn) {
    warnedFn = true
    console.error('ink: recipe params must be plain JSON (found a function or symbol); it cannot be part of the memo key')
  }
  return '"[unhashable]"'
}

export function knobsKey(k: Knobs): string {
  const f = (x: number) => String(Math.round(x * 100) / 100)
  return `${f(k.wobble)},${f(k.misreg)},${f(k.bleed)},${f(k.width)}`
}

export function bucketBox(w: number, h: number, q: readonly [number, number] = [4, 2]): Box {
  return { w: Math.max(q[0], Math.round(w / q[0]) * q[0]), h: Math.max(q[1], Math.round(h / q[1]) * q[1]) }
}

export interface Rng {
  (): number
  readonly seed: number
  range(a: number, b: number): number
  int(a: number, b: number): number
  chance(p: number): boolean
  sign(): 1 | -1
  pick<T>(arr: readonly T[]): T
  gauss(mean?: number, sd?: number): number
  fork(name: string | number): Rng
}

const AVALANCHE = 0x9e3779b9

function avalanche(h: number): number {
  h ^= h >>> 16
  h = Math.imul(h, 0x85ebca6b)
  h ^= h >>> 13
  h = Math.imul(h, 0xc2b2ae35)
  h ^= h >>> 16
  return h >>> 0
}

export function hashSeed(s: string | number): number {
  if (typeof s === 'number') return (Number.isFinite(s) ? avalanche(s >>> 0) : 0) || AVALANCHE
  let h = 0x811c9dc5
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i)
    h = Math.imul(h, 0x01000193)
  }
  return avalanche(h) || AVALANCHE
}

function derive(base: number, name: string): number {
  let h = (0x811c9dc5 ^ base) >>> 0
  h = Math.imul(h, 0x01000193)
  for (let i = 0; i < name.length; i++) {
    h ^= name.charCodeAt(i)
    h = Math.imul(h, 0x01000193)
  }
  return avalanche(h) || AVALANCHE
}

function build(base: number): Rng {
  let s = base
  let spare: number | null = null
  const next = (): number => {
    s = (s + 0x6d2b79f5) >>> 0
    let t = s
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
  const rng = next as Rng & { seed: number }
  rng.seed = base
  rng.range = (a, b) => a + (b - a) * next()
  rng.int = (a, b) => a + Math.floor(next() * (b - a + 1))
  rng.chance = (p) => next() < p
  rng.sign = () => (next() < 0.5 ? -1 : 1)
  rng.pick = (arr) => arr[Math.floor(next() * arr.length)]
  rng.gauss = (mean = 0, sd = 1) => {
    if (spare !== null) {
      const v = spare
      spare = null
      return mean + sd * v
    }
    let u = 0
    while (u === 0) u = next()
    const r = Math.sqrt(-2 * Math.log(u))
    const a = 2 * Math.PI * next()
    spare = r * Math.sin(a)
    return mean + sd * r * Math.cos(a)
  }
  rng.fork = (name) => build(derive(base, String(name)))
  return rng
}

export function makeRng(seed: string | number): Rng {
  return build(hashSeed(seed))
}

export const clamp = (v: number, a: number, b: number): number => (v < a ? a : v > b ? b : v)
export const lerp = (a: number, b: number, t: number): number => a + (b - a) * t
export const smooth = (t: number): number => (t <= 0 ? 0 : t >= 1 ? 1 : t * t * (3 - 2 * t))

import type { Line, PenName, PenSpec, Pt, StrokeOpts } from '@/lib/ink/types'
import type { Ink } from '@/lib/ink/builder'
import { clamp, type Rng } from '@/lib/ink/rng'
import { TAU, seg } from '@/lib/ink/geom'

export interface ShapeOpts {
  pen?: PenName | PenSpec
  opts?: StrokeOpts
  loose?: number
}

const dirv = (a: Pt, b: Pt): Pt => {
  const l = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1
  return [(b[0] - a[0]) / l, (b[1] - a[1]) / l]
}

function put(ink: Ink, salt: string, gen: (rng: Rng) => Line[], defaultPen: PenName, o: ShapeOpts): void {
  ink.lines(gen(ink.next(salt)), o.pen ?? defaultPen, o.opts)
}

export function chain(vs: Pt[], bows: number[], rad: number, rng: Rng, cnt = 14): Pt[] {
  const E = vs.length - 1
  const d: Pt[] = [], len: number[] = []
  for (let i = 0; i < E; i++) {
    d.push(dirv(vs[i], vs[i + 1]))
    len.push(Math.hypot(vs[i + 1][0] - vs[i][0], vs[i + 1][1] - vs[i][1]))
  }
  const rv: number[] = new Array(E + 1).fill(0)
  for (let j = 1; j < E; j++) {
    const r = Math.min(rad * (0.75 + rng() * 0.5), len[j - 1] * 0.45, len[j] * 0.45)
    rv[j] = r < 0.6 ? 0 : r
  }
  const out: Pt[] = []
  for (let i = 0; i < E; i++) {
    const s: Pt = [vs[i][0] + d[i][0] * rv[i], vs[i][1] + d[i][1] * rv[i]]
    const e: Pt = [vs[i + 1][0] - d[i][0] * rv[i + 1], vs[i + 1][1] - d[i][1] * rv[i + 1]]
    const pts = seg(s[0], s[1], e[0], e[1], bows[i] || 0, Math.max(2, Math.ceil(Math.hypot(e[0] - s[0], e[1] - s[1]) / cnt)))
    if (i > 0 && rv[i] === 0) pts.shift()
    out.push(...pts)
    if (i < E - 1 && rv[i + 1] > 0) {
      const V = vs[i + 1], r = rv[i + 1]
      const a = e
      const b: Pt = [V[0] + d[i + 1][0] * r, V[1] + d[i + 1][1] * r]
      const k = 0.9 + rng() * 0.1
      const c: Pt = [V[0] * k + ((a[0] + b[0]) / 2) * (1 - k), V[1] * k + ((a[1] + b[1]) / 2) * (1 - k)]
      for (let j = 1; j < 4; j++) {
        const t = j / 4, u = 1 - t
        out.push([u * u * a[0] + 2 * u * t * c[0] + t * t * b[0], u * u * a[1] + 2 * u * t * c[1] + t * t * b[1]])
      }
    }
  }
  return out
}

export function lineLines(rng: Rng, x1: number, y1: number, x2: number, y2: number, o: { bow?: number; single?: boolean } = {}): Line[] {
  const len = Math.hypot(x2 - x1, y2 - y1)
  const bow = clamp(rng.gauss(0, o.bow ?? 0.006) * len, -4, 4)
  if (len > 320 && !o.single) {
    const m = 0.45 + rng.range(0, 0.17)
    const mx = x1 + (x2 - x1) * m, my = y1 + (y2 - y1) * m
    return [
      { pts: seg(x1, y1, mx + 3, my + rng.gauss(0, 0.5), bow * 0.5, Math.ceil((len * m) / 12)), o: { end: 'soft', start: 'soft' } },
      { pts: seg(mx - 2, my + rng.gauss(0, 0.6), x2, y2, bow * 0.5, Math.ceil((len * (1 - m)) / 12)), o: { start: 'soft', end: 'flick' } },
    ]
  }
  return [{ pts: seg(x1, y1, x2, y2, bow, Math.max(4, Math.ceil(len / 12))), o: { end: 'flick' } }]
}
export function line(ink: Ink, x1: number, y1: number, x2: number, y2: number, o: ShapeOpts & { bow?: number; single?: boolean } = {}): void {
  put(ink, 'line', (r) => lineLines(r, x1, y1, x2, y2, o), 'pencil', o)
}

export function squiggleLines(rng: Rng, x: number, y: number, w: number, o: { h?: number; amp?: number; wl?: number } = {}): Line[] {
  const h = o.h ?? 12
  const amp = clamp(h * 0.2, 1.4, 3.2) * (o.amp ?? 1), wl = clamp(h * 1.1, 10, 18) * (o.wl ?? 1)
  const p1 = rng.range(0, TAU), p2 = rng.range(0, TAU), p3 = rng.range(0, TAU)
  const drift = rng.gauss(0, 0.6)
  const build = (xa: number, xb: number): Pt[] => {
    const pts: Pt[] = []
    let ph = rng.range(0, TAU)
    for (let xx = xa; xx <= xb; xx += 1.8) {
      ph += (1.8 / wl) * TAU * (1 + 0.22 * Math.sin(xx / 37 + p1) + 0.1 * Math.sin(xx / 11 + p2))
      const a = amp * (0.72 + 0.28 * Math.sin(xx / 53 + p3) + 0.12 * Math.sin(xx / 17 + p1))
      pts.push([xx, y + Math.sin(ph) * a + drift * Math.sin(((xx - x) / w) * Math.PI)])
    }
    return pts.filter((_, i) => i % 2 === 0)
  }
  if (w > 300) {
    const m = x + w * rng.range(0.46, 0.6)
    return [
      { pts: build(x, m + 3), o: { start: 'soft', end: 'soft', wobble: 0.5, speed: 1.1 } },
      { pts: build(m - 3, x + w), o: { start: 'soft', end: 'flick', wobble: 0.5, speed: 1.1 } },
    ]
  }
  return [{ pts: build(x, x + w), o: { end: 'flick', wobble: 0.5, speed: 1.1 } }]
}
export function squiggle(ink: Ink, x: number, y: number, w: number, o: ShapeOpts & { h?: number; amp?: number; wl?: number } = {}): void {
  put(ink, 'sq', (r) => squiggleLines(r, x, y, w, o), 'ink', o)
}

export function underlineLines(rng: Rng, x: number, y: number, w: number, o: { kind?: 'single' | 'double' | 'wavy' } = {}): Line[] {
  if (o.kind === 'wavy') return squiggleLines(rng, x, y, w, { h: 7, amp: 0.85 })
  const x1 = x - rng.range(0, 3), x2 = x + w + rng.range(-1, 4)
  const y1 = y + rng.gauss(0, 0.4), y2 = y - rng.range(0.3, 1.2 + 0.008 * w)
  const bow = rng.gauss(0, 0.004) * w + 0.3
  const out: Line[] = [{ pts: seg(x1, y1, x2, y2, bow, Math.max(4, Math.ceil(w / 14))), o: { end: 'flick', speed: 1.1 } }]
  if (o.kind === 'double') {
    const d = rng.range(3, 4.2)
    out.push({ pts: seg(x1 + rng.range(1, 6), y1 + d, x2 - rng.range(2, 10), y2 + d + rng.range(0, 1), rng.gauss(0, 0.004) * w, Math.max(4, Math.ceil(w / 14))), o: { end: 'flick', speed: 1.2 } })
  }
  return out
}
export function underline(ink: Ink, x: number, y: number, w: number, o: ShapeOpts & { kind?: 'single' | 'double' | 'wavy' } = {}): void {
  put(ink, 'ul', (r) => underlineLines(r, x, y, w, o), 'ink', o)
}

export function strikeLines(rng: Rng, x: number, y: number, w: number, o: { double?: boolean } = {}): Line[] {
  const tilt = rng.gauss(0, 0.012) * w
  const x1 = x - rng.range(1, 3), x2 = x + w + rng.range(0, 3)
  const so: StrokeOpts = { start: 'soft', end: 'flick', speed: 1.25, wobble: 0.6 }
  const out: Line[] = [{ pts: seg(x1, y + tilt / 2, x2, y - tilt / 2, rng.gauss(0, 0.003) * w, Math.max(3, Math.ceil(w / 16))), o: so }]
  if (o.double) out.push({ pts: seg(x1 + 2, y + 2.5, x2 - 1, y + 1.5 - tilt, 0, 6), o: so })
  return out
}
export function strike(ink: Ink, x: number, y: number, w: number, o: ShapeOpts & { double?: boolean } = {}): void {
  put(ink, 'st', (r) => strikeLines(r, x, y, w, o), 'red', o)
}

export interface BoxOpts {
  style?: 'two' | 'loop' | 'four'
  stubs?: boolean
  corner?: number
  ov?: number
  ghost?: number | false
  loose?: number
  wobble?: number
}

export function boxLines(rng: Rng, x: number, y: number, w: number, h: number, o: BoxOpts = {}): Line[] {
  const k = o.loose ?? 1
  const m = Math.min(w, h)
  const jc = clamp(0.012 * m, 0.12, 0.4) * k
  const tilt = rng.gauss(0, 0.0012) * k
  const ov = clamp(o.ov ?? 0.13 * m, 1.4, 5.2) * k
  const rad = o.corner ?? clamp(m * 0.09, 0.9, 3.4)
  let style = o.style ?? 'loop'
  if (style === 'four' && rad > 4.5) style = 'two'
  const stubs = style === 'four' ? true : (o.stubs ?? false)
  const over = (): number => (stubs ? (rng.chance(0.14) ? -rng.range(0.1, 0.35) * ov : rng.range(0.35, 1) * ov) : rng.range(-0.3, 0.3) * ov * 0.5)
  const C = (px: number, py: number, sy: number): Pt => [px + rng.gauss(0, jc), py + rng.gauss(0, jc) + sy * tilt * w]
  const TL = C(x, y, 0), TR = C(x + w, y, 1), BR = C(x + w, y + h, 1), BL = C(x, y + h, 0)
  const so: StrokeOpts = { speed: 1, wobble: 0.28 * (o.wobble ?? 1), dry: 0 }
  const lift = (l: number): number => rng.range(0.05, 0.32) * clamp(l / 110, 0.3, 1.2) * k
  const drift = (l: number): number => rng.gauss(0, 0.1) * clamp(l / 40, 0.4, 1) * k
  const ext = (a: Pt, b: Pt, e: number): Pt => {
    const d = dirv(a, b)
    return [b[0] + d[0] * e, b[1] + d[1] * e]
  }
  const out: Line[] = []
  if (o.ghost !== false && o.ghost !== undefined && m >= 24 && rng.chance(o.ghost)) {
    const g = rng.pick([[TL, TR], [BL, BR], [TL, BL]] as Array<[Pt, Pt]>)
    const s0 = ext(g[1], g[0], rng.range(2, 6)), e0 = ext(g[0], g[1], rng.range(2, 6))
    out.push({ pts: seg(s0[0] + 0.8, s0[1] + 1.2, e0[0] + 0.8, e0[1] + 1.2, 0.3, 4), pen: 'pencil', o: { alpha: 0.32, width: 0.7, end: 'soft', start: 'soft', wobble: 0.5, simple: true } })
  }
  if (style === 'four') {
    const edges: Array<[Pt, Pt, boolean]> = [[TL, TR, true], [TR, BR, false], [BR, BL, true], [TL, BL, false]]
    for (const [a, b, hz] of edges) {
      const s = ext(b, a, over()), e = ext(a, b, over())
      const l = Math.hypot(e[0] - s[0], e[1] - s[1])
      const bow = hz ? (e[0] - s[0] > 0 ? -lift(l) : lift(l)) : drift(l)
      out.push({ pts: seg(s[0], s[1], e[0], e[1], bow, Math.max(4, Math.ceil(l / 14))), o: { ...so, end: rng.chance(0.4) ? 'pool' : 'flick' } })
    }
    return out
  }
  if (style === 'loop') {
    const t0 = rng.range(0.35, 0.65)
    const S: Pt = [TL[0] + (TR[0] - TL[0]) * t0, TL[1] + (TR[1] - TL[1]) * t0]
    const run = Math.min(0.06 * w, rng.range(1.6, 2.6))
    const vs: Pt[] = [S, TR, BR, BL, TL, [S[0] + run, S[1]]]
    const bows = [-lift(w * (1 - t0)), drift(h), lift(w), drift(h), -lift(w * t0 + run)]
    out.push({ pts: chain(vs, bows, rad, rng), o: { ...so, end: 'soft', start: 'soft' } })
    return out
  }
  if (rad > 4.5) {
    const fa = rng.range(0.3, 0.7), fb = rng.range(0.3, 0.7)
    const onL = (f: number, e: number): Pt => [TL[0] + (BL[0] - TL[0]) * f, TL[1] + (BL[1] - TL[1]) * f + e]
    const onR = (f: number, e: number): Pt => [TR[0] + (BR[0] - TR[0]) * f, TR[1] + (BR[1] - TR[1]) * f + e]
    out.push({ pts: chain([onL(fa, over()), TL, TR, onR(fb, over())], [drift(h), -lift(w), drift(h)], rad, rng), o: { ...so, end: 'flick', start: 'pool' } })
    out.push({ pts: chain([onR(fb, -over() * 0.6), BR, BL, onL(fa, -over())], [drift(h), lift(w), drift(h)], rad, rng), o: { ...so, end: 'flick', start: 'soft' } })
    return out
  }
  const A0 = ext(TR, TL, over()), A2 = ext(TR, BR, over())
  out.push({ pts: chain([A0, TR, A2], [-lift(w), drift(h)], rad, rng), o: { ...so, end: 'flick', start: 'pool' } })
  const B0 = ext(BL, TL, over() * 0.6)
  const B3: Pt = [BR[0] + over(), BR[1] + rng.gauss(0, 0.3)]
  out.push({ pts: chain([B0, BL, B3], [drift(h), -lift(w)], rad, rng), o: { ...so, end: 'flick', start: 'soft' } })
  return out
}
export function box(ink: Ink, x: number, y: number, w: number, h: number, o: ShapeOpts & BoxOpts = {}): void {
  put(ink, 'box', (r) => boxLines(r, x, y, w, h, o), 'ink', o)
}

export function loopLines(rng: Rng, cx: number, cy: number, rx: number, ry: number, o: { turns?: number; a0?: number; drift?: number; breathe?: number; loose?: number; clean?: boolean } = {}): Line[] {
  if (o.clean) {
    const a0 = o.a0 ?? rng.range(-2.9, -1.8)
    const steps = Math.max(24, Math.ceil((rx + ry) * 0.6))
    const turn = 1 + 2.2 / Math.max(6, Math.PI * (rx + ry))
    const ph = rng.range(0, TAU)
    const pts: Pt[] = []
    for (let i = 0; i <= steps; i++) {
      const a = a0 + (i / steps) * turn * TAU
      const kk = 1 + 0.006 * Math.sin(2 * a + ph)
      pts.push([cx + Math.cos(a) * rx * kk, cy + Math.sin(a) * ry * kk])
    }
    return [{ pts, o: { end: 'soft', start: 'soft', wobble: 0.25, speed: 1, dry: 0 } }]
  }
  const turns = o.turns ?? rng.range(1.05, 1.18)
  const a0 = o.a0 ?? rng.range(-2.9, -1.8)
  const tilt = rng.gauss(0, 0.05) * (o.loose ?? 1)
  const drift = o.drift ?? rng.range(-0.07, 0.05)
  const breathe = o.breathe ?? 0.035
  const ph = rng.range(0, TAU)
  const steps = Math.max(16, Math.ceil((rx + ry) * turns * 0.5))
  const pts: Pt[] = []
  for (let i = 0; i <= steps; i++) {
    const t = i / steps, a = a0 + t * turns * TAU
    const kk = 1 + breathe * Math.sin(2 * a + ph) + drift * t
    const ex = Math.cos(a) * rx * kk, ey = Math.sin(a) * ry * kk
    pts.push([cx + ex * Math.cos(tilt) - ey * Math.sin(tilt), cy + ex * Math.sin(tilt) + ey * Math.cos(tilt)])
  }
  return [{ pts, o: { end: 'flick', start: 'pool', wobble: 0.7, speed: 1 } }]
}
export function loop(ink: Ink, cx: number, cy: number, rx: number, ry: number, o: ShapeOpts & { turns?: number; a0?: number; drift?: number; breathe?: number; clean?: boolean } = {}): void {
  put(ink, 'loop', (r) => loopLines(r, cx, cy, rx, ry, o), 'ink', o)
}

export function arrowLines(rng: Rng, x1: number, y1: number, x2: number, y2: number, o: { head?: 'v' | 'two' | 'open' | 'solid' | 'none'; curl?: boolean; curve?: number; headLen?: number } = {}): Line[] {
  const len = Math.hypot(x2 - x1, y2 - y1)
  const bow = (o.curve ?? rng.range(-0.1, 0.1)) * len
  let shaft = seg(x1, y1, x2, y2, bow, Math.max(6, Math.ceil(len / 8)))
  if (o.curl) {
    const m = Math.floor(shaft.length * 0.5), pm = shaft[m], pn = shaft[m + 1] || pm
    const d0 = dirv(pm, pn), r0 = Math.min(9, len * 0.09)
    const loopPts: Pt[] = []
    for (let i = 0; i <= 14; i++) {
      const a = -Math.PI / 2 + (i / 14) * TAU
      const lx = Math.cos(a) * r0, ly = Math.sin(a) * r0 * 1.15 + r0 * 1.15
      loopPts.push([pm[0] + d0[0] * lx * 1.1 + d0[1] * (ly - r0 * 1.15), pm[1] + d0[1] * lx * 1.1 - d0[0] * (ly - r0 * 1.15)])
    }
    shaft = [...shaft.slice(0, m), ...loopPts, ...shaft.slice(m + 1)]
  }
  const out: Line[] = [{ pts: shaft, o: { end: 'flick', start: 'pool' } }]
  const style = o.head ?? 'v'
  if (style === 'none') return out
  const p = shaft[shaft.length - 1], q = shaft[shaft.length - 3] || shaft[0]
  const d = dirv(q, p)
  const hl = o.headLen ?? clamp(len * 0.2, 6, 12)
  const s1 = rng.range(0.42, 0.6), s2 = rng.range(0.42, 0.6)
  const tip: Pt = [p[0] + rng.gauss(0, 0.3), p[1] + rng.gauss(0, 0.3)]
  const rot = (a: number, l: number): Pt => [tip[0] - (d[0] * Math.cos(a) - d[1] * Math.sin(a)) * l, tip[1] - (d[0] * Math.sin(a) + d[1] * Math.cos(a)) * l]
  const b1 = rot(s1, hl), b2 = rot(-s2, hl * rng.range(0.85, 1.1))
  if (style === 'v') {
    out.push({ pts: [b1, seg(b1[0], b1[1], tip[0], tip[1], rng.gauss(0, 0.3), 3)[1], tip, seg(tip[0], tip[1], b2[0], b2[1], rng.gauss(0, 0.3), 3)[1], b2], o: { end: 'flick', start: 'soft', wobble: 0.5 } })
  } else if (style === 'two') {
    out.push({ pts: seg(b1[0], b1[1], tip[0], tip[1], 0.3, 4), o: { end: 'pool', start: 'soft', wobble: 0.5 } })
    out.push({ pts: seg(tip[0], tip[1], b2[0], b2[1], -0.3, 4), o: { end: 'flick', start: 'soft', wobble: 0.5 } })
  } else if (style === 'open') {
    out.push({ pts: [b1, tip, b2], o: { end: 'soft', start: 'soft', wobble: 0.4, poly: true } })
  } else {
    const toward = (a: Pt, b: Pt, t: number): Pt => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]
    out.push({ pts: [b1, tip, b2, toward(b1, tip, 0.12)], o: { end: 'pool', wobble: 0.3, width: 1.1 } })
    const c: Pt = [(b1[0] + b2[0] + tip[0]) / 3, (b1[1] + b2[1] + tip[1]) / 3]
    out.push({ pts: [toward(b1, c, 0.35), toward(b2, c, 0.3), toward(tip, c, 0.3), c], o: { end: 'pool', wobble: 0.2, width: 1.3 } })
  }
  return out
}
export function arrow(ink: Ink, x1: number, y1: number, x2: number, y2: number, o: ShapeOpts & { head?: 'v' | 'two' | 'open' | 'solid' | 'none'; curl?: boolean; curve?: number; headLen?: number } = {}): void {
  put(ink, 'arrow', (r) => arrowLines(r, x1, y1, x2, y2, o), 'ink', o)
}

export function checkLines(rng: Rng, x: number, y: number, s: number): Line[] {
  const a: Pt = [x + s * rng.range(0, 0.1), y + s * rng.range(0.45, 0.58)]
  const b: Pt = [x + s * rng.range(0.32, 0.42), y + s * rng.range(0.86, 0.96)]
  const c: Pt = [x + s * rng.range(0.9, 1.02), y + s * rng.range(0, 0.1)]
  const mid: Pt = [b[0] + (c[0] - b[0]) * 0.45 - s * 0.05, b[1] + (c[1] - b[1]) * 0.45 + s * 0.02]
  return [{ pts: [...seg(a[0], a[1], b[0], b[1], s * 0.03, 4), mid, c], o: { start: 'pool', end: 'flick', speed: 1.1, wobble: 0.5 } }]
}
export function check(ink: Ink, x: number, y: number, s: number, o: ShapeOpts = {}): void {
  put(ink, 'check', (r) => checkLines(r, x, y, s), 'greenfelt', o)
}

export function crossLines(rng: Rng, x: number, y: number, s: number): Line[] {
  const j = (): number => rng.gauss(0, 0.04 * s)
  return [
    { pts: seg(x + j(), y + j(), x + s + j(), y + s + j(), rng.gauss(0, 0.03 * s), 5), o: { end: 'flick', wobble: 0.5 } },
    { pts: seg(x + s + j(), y + j(), x + j(), y + s + j(), rng.gauss(0, 0.03 * s), 5), o: { end: 'flick', wobble: 0.5 } },
  ]
}
export function cross(ink: Ink, x: number, y: number, s: number, o: ShapeOpts = {}): void {
  put(ink, 'cross', (r) => crossLines(r, x, y, s), 'redfelt', o)
}

export function asteriskLines(rng: Rng, cx: number, cy: number, s: number): Line[] {
  const out: Line[] = []
  for (let k = 0; k < 3; k++) {
    const a = Math.PI / 2 + (k * Math.PI) / 3 + rng.gauss(0, 0.07)
    const l = 0.5 * s * rng.range(0.85, 1)
    const c: Pt = [cx + rng.gauss(0, 0.03 * s), cy + rng.gauss(0, 0.03 * s)]
    out.push({ pts: seg(c[0] - Math.cos(a) * l, c[1] - Math.sin(a) * l, c[0] + Math.cos(a) * l, c[1] + Math.sin(a) * l, rng.gauss(0, 0.3), 4), o: { end: 'flick', wobble: 0.4 } })
  }
  return out
}
export function asterisk(ink: Ink, cx: number, cy: number, s: number, o: ShapeOpts = {}): void {
  put(ink, 'ast', (r) => asteriskLines(r, cx, cy, s), 'redfelt', o)
}

export function spiralLines(rng: Rng, cx: number, cy: number, r0: number, o: { turns?: number; steps?: number; shrink?: number } = {}): Line[] {
  const turns = o.turns ?? 2.3
  const steps = o.steps ?? 26
  const a0 = rng.range(0, TAU)
  const pts: Pt[] = []
  for (let i = 0; i <= steps; i++) {
    const t = i / steps
    const r = r0 * (1 - (o.shrink ?? 0.78) * t)
    const a = a0 + t * turns * TAU + rng.range(0, 0.2)
    pts.push([cx + Math.cos(a) * r, cy + Math.sin(a) * r * 0.94])
  }
  return [{ pts, o: { end: 'pool', start: 'soft', wobble: 0.3, speed: 0.9 } }]
}
export function spiral(ink: Ink, cx: number, cy: number, r: number, o: ShapeOpts & { turns?: number; steps?: number; shrink?: number } = {}): void {
  put(ink, 'spiral', (rg) => spiralLines(rg, cx, cy, r, o), 'ink', o)
}

export function starLines(rng: Rng, cx: number, cy: number, r: number): Line[] {
  const pts: Pt[] = []
  const a0 = -Math.PI / 2 + rng.gauss(0, 0.06)
  for (let i = 0; i <= 5; i++) {
    const a = a0 + ((i * 2) % 5) * (TAU / 5)
    const rr = r * rng.range(0.9, 1.05)
    pts.push([cx + Math.cos(a) * rr, cy + Math.sin(a) * rr])
  }
  pts.push([pts[0][0] + rng.gauss(0, 0.05 * r) + 0.1 * r, pts[0][1] + 0.18 * r])
  return [{ pts, o: { poly: true, wobble: 0.5, end: 'flick' } }]
}
export function star(ink: Ink, cx: number, cy: number, r: number, o: ShapeOpts = {}): void {
  put(ink, 'star', (rg) => starLines(rg, cx, cy, r), 'ink', o)
}

export function tallyLines(rng: Rng, x: number, y: number, count: number, gh: number): { lines: Line[]; width: number } {
  const step = 0.26 * gh, gw = 1.05 * gh + 6
  const lines: Line[] = []
  let gx = x
  let left = count
  while (left > 0) {
    const n5 = Math.min(5, left)
    left -= n5
    const up = Math.min(4, n5)
    for (let i = 0; i < up; i++) {
      const lx = gx + i * step + rng.gauss(0, 0.35)
      lines.push({ pts: seg(lx + rng.gauss(0.4, 0.4), y + rng.gauss(0, 0.5), lx - rng.gauss(0.3, 0.3), y + gh + rng.gauss(0, 0.6), rng.gauss(0, 0.4), 4), o: { end: rng.chance(0.5) ? 'flick' : 'pool', speed: 1.15, wobble: 0.5 } })
    }
    if (n5 === 5) lines.push({ pts: seg(gx - 0.55 * step, y + 0.78 * gh + rng.gauss(0, 0.6), gx + 3.55 * step, y + 0.2 * gh + rng.gauss(0, 0.6), rng.gauss(0, 0.5), 5), o: { end: 'flick', speed: 1.25, wobble: 0.5 } })
    gx += gw
  }
  return { lines, width: gx - x }
}
export function tally(ink: Ink, x: number, y: number, count: number, gh: number, o: ShapeOpts = {}): number {
  const t = tallyLines(ink.next('tally'), x, y, count, gh)
  ink.lines(t.lines, o.pen ?? 'ink', o.opts)
  return t.width
}

export function bracketLines(rng: Rng, x: number, y: number, h: number, o: { kind?: 'square' | 'curly' | 'round'; dir?: 1 | -1 } = {}): Line[] {
  const d = o.dir ?? 1
  const tip = clamp(h * 0.12, 3, 9)
  const kind = o.kind ?? 'square'
  const so: StrokeOpts = { end: 'flick', wobble: 0.5 }
  if (kind === 'square') {
    const rad = Math.min(0.35 * tip, 2.2)
    const pts: Pt[] = [
      [x + d * tip * rng.range(0.85, 1.1), y + rng.gauss(0, 0.5)],
      [x + d * rad, y + rng.gauss(0, 0.2)],
      [x + rng.gauss(0, 0.2), y + rad],
      ...seg(x + rng.gauss(0, 0.2), y + rad, x + rng.gauss(0, 0.6), y + h - rad, rng.gauss(0, 0.004) * h, 6).slice(1),
      [x + d * rad, y + h + rng.gauss(0, 0.2)],
      [x + d * tip * rng.range(0.85, 1.15), y + h + rng.gauss(0, 0.6)],
    ]
    return [{ pts, o: so }]
  }
  if (kind === 'curly') {
    const m = y + h * rng.range(0.47, 0.53)
    return [{ pts: [[x + d * tip, y], [x + 0.35 * d * tip, y + 0.06 * h], [x + 0.3 * d * tip, m - 0.12 * h], [x - 0.15 * d * tip, m], [x + 0.3 * d * tip, m + 0.12 * h], [x + 0.35 * d * tip, y + h * 0.94], [x + d * tip, y + h]], o: so }]
  }
  const pts: Pt[] = []
  for (let i = 0; i <= 12; i++) {
    const t = i / 12
    pts.push([x + d * tip * (1 - Math.sin(Math.PI * t)), y + h * t])
  }
  return [{ pts, o: so }]
}
export function bracket(ink: Ink, x: number, y: number, h: number, o: ShapeOpts & { kind?: 'square' | 'curly' | 'round'; dir?: 1 | -1 } = {}): void {
  put(ink, 'br', (r) => bracketLines(r, x, y, h, o), 'pencil', o)
}

export function cloudLines(rng: Rng, cx: number, cy: number, w: number, h: number, o: { bulge?: number } = {}): Line[] {
  const rx = w / 2, ry = h / 2
  const bumps = clamp(Math.round((Math.PI * (rx + ry)) / clamp(0.32 * Math.min(w, h), 9, 26)), 6, 40)
  const a0 = -Math.PI / 2 + rng.gauss(0, 0.3)
  const sizes = Array.from({ length: bumps }, () => rng.range(0.75, 1.25))
  const tot = sizes.reduce((a, b) => a + b, 0)
  const pts: Pt[] = []
  let a = a0
  const P = (ang: number): Pt => [cx + Math.cos(ang) * rx, cy + Math.sin(ang) * ry]
  for (let i = 0; i < bumps + 1; i++) {
    const i2 = i % bumps
    const da = (sizes[i2] / tot) * TAU
    const p0 = P(a), p1 = P(a + da)
    const L = Math.hypot(p1[0] - p0[0], p1[1] - p0[1])
    const bulge = Math.min(0.42 * L, o.bulge ?? L * 0.3) * rng.range(0.8, 1.1)
    const nx = (p0[0] + p1[0]) / 2 - cx, ny = (p0[1] + p1[1]) / 2 - cy
    const nl = Math.hypot(nx, ny) || 1
    for (let k = i === 0 ? 0 : 1; k <= 6; k++) {
      const t = k / 6, b = Math.sin(Math.PI * t) * bulge
      pts.push([p0[0] + (p1[0] - p0[0]) * t + (nx / nl) * b, p0[1] + (p1[1] - p0[1]) * t + (ny / nl) * b])
    }
    a += da
  }
  pts.push([pts[1][0] + 1.5, pts[1][1] + 0.6])
  return [{ pts, o: { end: 'flick', wobble: 0.5, speed: 1.05 } }]
}
export function cloud(ink: Ink, cx: number, cy: number, w: number, h: number, o: ShapeOpts & { bulge?: number } = {}): void {
  put(ink, 'cloud', (r) => cloudLines(r, cx, cy, w, h, o), 'pencil', o)
}

export function scribbleLines(rng: Rng, x: number, y: number, w: number, h: number): Line[] {
  const step = Math.max(2.2, 0.28 * h)
  const nn = Math.max(3, Math.round(w / step))
  const lean = rng.gauss(0.18, 0.08) * h
  const pts: Pt[] = []
  for (let k = 0; k <= nn; k++) {
    const up = k % 2 === 0
    pts.push([clamp(x + (k / nn) * w + rng.gauss(0, 0.18 * step) + (up ? -lean / 2 : lean / 2), x, x + w), up ? y + rng.range(0, 0.2) * h : y + rng.range(0.8, 1) * h])
  }
  return [{ pts, o: { end: 'flick', speed: 1.3, wobble: 0.6 } }]
}
export function scribble(ink: Ink, x: number, y: number, w: number, h: number, o: ShapeOpts = {}): void {
  put(ink, 'scrib', (r) => scribbleLines(r, x, y, w, h), 'red', o)
}

export function burstLines(rng: Rng, cx: number, cy: number, r: number, o: { rays?: number } = {}): Line[] {
  const k = o.rays ?? 10
  const a0 = rng.range(0, TAU)
  const out: Line[] = []
  for (let i = 0; i < k; i++) {
    const a = a0 + (i / k) * TAU + rng.gauss(0, 0.07)
    const r0 = r * rng.range(0.42, 0.52), r1 = r * (i % 2 ? rng.range(0.78, 0.9) : rng.range(0.98, 1.1))
    out.push({ pts: seg(cx + Math.cos(a) * r0, cy + Math.sin(a) * r0, cx + Math.cos(a) * r1, cy + Math.sin(a) * r1, rng.gauss(0, 0.25), 3), o: { end: 'flick', start: 'soft', wobble: 0.3, speed: 1.2 } })
  }
  return out
}
export function burst(ink: Ink, cx: number, cy: number, r: number, o: ShapeOpts & { rays?: number } = {}): void {
  put(ink, 'burst', (rg) => burstLines(rg, cx, cy, r, o), 'redfelt', o)
}

export interface FocusRingOpts {
  shape?: 'rect' | 'ellipse'
  gap?: number
  r?: number
  ticks?: boolean
}

export function focusRingLines(rng: Rng, x: number, y: number, w: number, h: number, o: FocusRingOpts = {}): Line[] {
  const gap = o.gap ?? 4
  const out: Line[] = []
  const rect = (o.shape ?? 'rect') === 'rect'
  const X = x - gap, Y = y - gap, W = w + gap * 2, H = h + gap * 2
  if (rect) {
    const R = (o.r ?? 4) + gap
    out.push(...boxLines(rng.fork('ring'), X, Y, W, H, { style: 'loop', corner: R, stubs: false, ghost: false, ov: 1.5 }))
  } else {
    out.push(...loopLines(rng.fork('ring'), x + w / 2, y + h / 2, W / 2, H / 2, { clean: true }))
  }
  if (o.ticks === true) {
    const tr = rng.fork('ticks')
    if (rect) {
      const cs: Array<[number, number, number, number]> = [[X, Y, -1, -1], [X + W, Y, 1, -1], [X + W, Y + H, 1, 1], [X, Y + H, -1, 1]]
      const inset = ((o.r ?? 4) + gap) * (1 - Math.SQRT1_2)
      for (const [cx, cy, sx, sy] of cs) {
        if (tr() < 0.15) continue
        const a = Math.atan2(sy, sx) + tr.gauss(0, 0.15)
        const r0 = 2 + inset, r1 = r0 + 3 + tr() * 2.5
        out.push({ pts: seg(cx + Math.cos(a) * r0, cy + Math.sin(a) * r0, cx + Math.cos(a) * r1, cy + Math.sin(a) * r1, 0.3, 3), o: { end: 'flick', start: 'soft', wobble: 0.3, width: 0.8 } })
      }
    } else {
      const cx = x + w / 2, cy = y + h / 2
      for (const base of [-0.75 * Math.PI, 0.25 * Math.PI]) {
        const a = base + tr.gauss(0, 0.2)
        const ex = Math.cos(a), ey = Math.sin(a)
        const r0 = Math.hypot(ex * (W / 2), ey * (H / 2)) + 2, r1 = r0 + 3 + tr() * 2.5
        out.push({ pts: seg(cx + ex * r0, cy + ey * r0, cx + ex * r1, cy + ey * r1, 0.3, 3), o: { end: 'flick', start: 'soft', wobble: 0.3, width: 0.8 } })
      }
    }
  }
  return out
}
export function focusRing(ink: Ink, x: number, y: number, w: number, h: number, o: ShapeOpts & FocusRingOpts = {}): void {
  put(ink, 'focus', (r) => focusRingLines(r, x, y, w, h, o), 'focus', o)
}

export function dashedBoxLines(rng: Rng, x: number, y: number, w: number, h: number, o: { r?: number; dash?: number; gap?: number } = {}): Line[] {
  const r = Math.min(o.r ?? 4, w / 2, h / 2)
  const cornerPts: Pt[] = []
  const per = 5
  const arc = (cx: number, cy: number, a0: number): void => {
    for (let i = 0; i <= per; i++) {
      const a = a0 + (i / per) * (Math.PI / 2)
      cornerPts.push([cx + Math.cos(a) * r, cy + Math.sin(a) * r])
    }
  }
  if (r < 0.5) cornerPts.push([x, y], [x + w, y], [x + w, y + h], [x, y + h])
  else {
    arc(x + w - r, y + r, -Math.PI / 2)
    arc(x + w - r, y + h - r, 0)
    arc(x + r, y + h - r, Math.PI / 2)
    arc(x + r, y + r, Math.PI)
  }
  const closed = [...cornerPts, cornerPts[0]]
  const cum = [0]
  for (let i = 1; i < closed.length; i++) cum.push(cum[i - 1] + Math.hypot(closed[i][0] - closed[i - 1][0], closed[i][1] - closed[i - 1][1]))
  const per_ = cum[cum.length - 1]
  const at = (d: number): Pt => {
    d = ((d % per_) + per_) % per_
    let i = 1
    while (i < cum.length - 1 && cum[i] < d) i++
    const t = (d - cum[i - 1]) / (cum[i] - cum[i - 1] || 1)
    return [closed[i - 1][0] + (closed[i][0] - closed[i - 1][0]) * t, closed[i - 1][1] + (closed[i][1] - closed[i - 1][1]) * t]
  }
  const dash = o.dash ?? clamp(Math.min(w, h) * 0.3, 5, 9), gap = o.gap ?? dash * 0.55
  const out: Line[] = []
  let d = rng() * (dash + gap)
  const end = per_ + d - 3
  while (d < end) {
    const len = dash * rng.range(0.75, 1.2)
    const pts: Pt[] = []
    for (let k = 0; k <= 3; k++) pts.push(at(d + (len * k) / 3))
    out.push({ pts, o: { start: 'soft', end: 'soft', wobble: 0.5, simple: true } })
    d += len + gap * rng.range(0.7, 1.3)
  }
  return out
}
export function dashedBox(ink: Ink, x: number, y: number, w: number, h: number, o: ShapeOpts & { r?: number; dash?: number; gap?: number } = {}): void {
  put(ink, 'dash', (r) => dashedBoxLines(r, x, y, w, h, o), 'pencil', o)
}

import { GRAIN_TILES, type GrainMaskKind, type GrainTile } from '@/lib/ink/textures.generated'
import {
  PAPER_TILES, PAPER_RELIEF, PAPER_SLIP, PAPER_FIBRE, PAPER_CLOUD, PAPER_LINEN, PAPER_KRAFT,
  type PaperTile, type PaperTileName,
} from '@/lib/ink/textures-paper.generated'

export type { GrainMaskKind, GrainTile, PaperTile, PaperTileName }
export { GRAIN_TILES, PAPER_TILES }

export const GRAIN_KINDS = ['felt', 'marker', 'graphite', 'waxy', 'stamp'] as const satisfies readonly GrainMaskKind[]

export const GRAIN_VARIANTS = 6

export function grainPhase(variant: number): { x: number; y: number; rot: 0 | 90 | 180 | 270 } {
  const v = ((Math.trunc(variant) % GRAIN_VARIANTS) + GRAIN_VARIANTS) % GRAIN_VARIANTS
  const rots = [0, 90, 180, 270, 0, 180] as const
  return { x: (v * 0.618034) % 1, y: (v * 0.381966 + 0.17) % 1, rot: rots[v] }
}

const idPrefix = (p?: string) => p ?? 'll'
const num = (v: number) => String(Math.round(v * 100) / 100)

export function grainMaskId(kind: GrainMaskKind, variant?: number, prefix?: string): string {
  if (variant === undefined) return `${idPrefix(prefix)}-${kind}`
  return `${idPrefix(prefix)}-${kind}-${((Math.trunc(variant) % GRAIN_VARIANTS) + GRAIN_VARIANTS) % GRAIN_VARIANTS}`
}

export const grainMaskUrl = (kind: GrainMaskKind, variant?: number, prefix?: string) => `url(#${grainMaskId(kind, variant, prefix)})`

export const grainVariantFor = (seed: number): number => (Math.imul(seed | 0, 0x9e3779b1) >>> 7) % GRAIN_VARIANTS

export interface MaskDefsOptions {
  kinds?: readonly GrainMaskKind[]
  prefix?: string
  region?: { x: number; y: number; width: number; height: number } | 'bbox'
}

const DEFAULT_REGION = { x: -2048, y: -2048, width: 8192, height: 8192 }

export function svgMaskDefs(o: MaskDefsOptions = {}): string {
  const kinds = o.kinds ?? GRAIN_KINDS
  const p = idPrefix(o.prefix)
  const region = o.region ?? DEFAULT_REGION
  const maskAttrs = region === 'bbox' ? 'x="-0.1" y="-0.1" width="1.2" height="1.2"' : `maskUnits="userSpaceOnUse" x="${region.x}" y="${region.y}" width="${region.width}" height="${region.height}"`
  const fill = region === 'bbox' ? { x: -4000, y: -4000, width: 9000, height: 9000 } : region
  let s = ''
  for (const kind of kinds) {
    const t = GRAIN_TILES[kind]
    s += `<image id="${p}-${kind}-img" width="${t.css}" height="${t.css}" href="${t.uri}"/>`
    for (let v = 0; v < GRAIN_VARIANTS; v++) {
      const ph = grainPhase(v)
      const tf = ` patternTransform="translate(${num(ph.x * t.css)} ${num(ph.y * t.css)})${ph.rot ? ` rotate(${ph.rot})` : ''}"`
      s += `<pattern id="${p}-${kind}-pat-${v}" width="${t.css}" height="${t.css}" patternUnits="userSpaceOnUse"${tf}><use href="#${p}-${kind}-img"/></pattern>`
    }
    const rect = (v: number) => `<rect x="${fill.x}" y="${fill.y}" width="${fill.width}" height="${fill.height}" fill="url(#${p}-${kind}-pat-${v})"/>`
    s += `<mask id="${p}-${kind}" ${maskAttrs}>${rect(0)}</mask>`
    for (let v = 0; v < GRAIN_VARIANTS; v++) s += `<mask id="${p}-${kind}-${v}" ${maskAttrs}>${rect(v)}</mask>`
  }
  return s
}

export const PAPER_STOCKS = {
  paper: 'var(--ll-paper)',
  slip: 'var(--ll-slip)',
  card: 'var(--ll-card)',
  graph: 'var(--ll-graph)',
  check: 'var(--ll-check)',
  kraft: 'var(--ll-kraft)',
  yellow: 'var(--ll-sticky-yellow)',
  green: 'var(--ll-sticky-green)',
  orange: 'var(--ll-sticky-orange)',
  pink: 'var(--ll-sticky-pink)',
  blue: 'var(--ll-sticky-blue)',
} as const

export type PaperStock = keyof typeof PAPER_STOCKS | (string & {})

export interface TextureStyle {
  backgroundColor: string
  backgroundImage: string
  backgroundSize: string
  backgroundPosition: string
  backgroundRepeat: string
}

export interface PaperBackgroundOptions {
  tooth?: 'cold' | 'fine'
  seed?: string | number
  layers?: Partial<Record<'relief' | 'slip' | 'fibre' | 'cloud' | 'kraft', boolean>>
}

function hash32(seed: string | number): number {
  let h = 0x811c9dc5
  const s = String(seed)
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i)
    h = Math.imul(h, 0x01000193)
  }
  h ^= h >>> 16
  h = Math.imul(h, 0x85ebca6b)
  h ^= h >>> 13
  return h >>> 0
}

function offsetFor(seed: string | number | undefined, i: number, w: number, h: number): string {
  if (seed === undefined) return '0 0'
  const a = hash32(`${seed}:${i}`)
  return `${-(a % Math.round(w))}px ${-((a >>> 11) % Math.round(h))}px`
}

const url = (uri: string) => `url(${uri})`
const tileSize = (t: PaperTile) => `${t.cssWidth}px ${t.cssHeight}px`

export function paperBackground(stock: PaperStock = 'paper', o: PaperBackgroundOptions = {}): TextureStyle {
  const cold = (o.tooth ?? (stock === 'paper' ? 'cold' : 'fine')) === 'cold'
  const on = { relief: cold && stock !== 'kraft', slip: !cold && stock !== 'kraft', fibre: true, cloud: true, kraft: stock === 'kraft', ...o.layers }
  const order: PaperTileName[] = (['fibre', 'kraft', 'relief', 'slip', 'cloud'] as const).filter((n) => on[n])
  const byName = { relief: PAPER_RELIEF, slip: PAPER_SLIP, fibre: PAPER_FIBRE, cloud: PAPER_CLOUD, kraft: PAPER_KRAFT } as Partial<Record<PaperTileName, PaperTile>>
  const tiles = order.map((n) => byName[n]!)
  const color = (PAPER_STOCKS as Record<string, string>)[stock] ?? stock
  return {
    backgroundColor: color,
    backgroundImage: tiles.map((t) => url(t.uri)).join(', '),
    backgroundSize: tiles.map(tileSize).join(', '),
    backgroundPosition: tiles.map((t, i) => offsetFor(o.seed, i, t.cssWidth, t.cssHeight)).join(', '),
    backgroundRepeat: tiles.map(() => 'repeat').join(', '),
  }
}

export interface DeskBackgroundOptions {
  vignette?: number
  seed?: string | number
}

export function deskBackground(o: DeskBackgroundOptions = {}): TextureStyle {
  const v = o.vignette ?? 0.05
  const vig = `radial-gradient(ellipse 92% 82% at 50% 40%, rgb(var(--ll-shade) / 0) 52%, rgb(var(--ll-shade) / ${v}) 100%)`
  const linen = PAPER_LINEN
  return {
    backgroundColor: 'var(--ll-desk)',
    backgroundImage: [vig, url(linen.uri)].join(', '),
    backgroundSize: ['100% 100%', tileSize(linen)].join(', '),
    backgroundPosition: ['0 0', offsetFor(o.seed, 0, linen.cssWidth, linen.cssHeight)].join(', '),
    backgroundRepeat: ['no-repeat', 'repeat'].join(', '),
  }
}

export function styleToCss(s: TextureStyle): string {
  return `background-color:${s.backgroundColor};background-image:${s.backgroundImage};background-size:${s.backgroundSize};background-position:${s.backgroundPosition};background-repeat:${s.backgroundRepeat}`
}

export const paperCss = (stock?: PaperStock, o?: PaperBackgroundOptions) => styleToCss(paperBackground(stock, o))

export const deskCss = (o?: DeskBackgroundOptions) => styleToCss(deskBackground(o))

export function textureCssVars(names: readonly PaperTileName[] = ['relief', 'slip', 'fibre', 'cloud', 'mottle', 'linen', 'kraft']): string {
  return `:root{${names.map((n) => `--ll-tex-${n}:${url(PAPER_TILES[n].uri)}`).join(';')}}`
}

export interface PatternDefsOptions {
  tiles?: readonly PaperTileName[]
  prefix?: string
}

export const PATTERN_OFFSETS = [
  [0, 0],
  [67, 113],
  [131, 29],
  [23, 171],
] as const

export function svgPatternDefs(o: PatternDefsOptions = {}): string {
  const names = o.tiles ?? (['relief', 'slip', 'fibre', 'cloud', 'mottle', 'linen', 'kraft'] as const)
  const p = idPrefix(o.prefix)
  let s = ''
  for (const name of names) {
    const t = PAPER_TILES[name]
    s += `<image id="${p}-tex-${name}-img" width="${t.cssWidth}" height="${t.cssHeight}" href="${t.uri}"/>`
    PATTERN_OFFSETS.forEach(([x, y], i) => {
      const id = i === 0 ? `${p}-tex-${name}` : `${p}-tex-${name}-${i}`
      const tf = i === 0 ? '' : ` patternTransform="translate(${x} ${y})"`
      s += `<pattern id="${id}" width="${t.cssWidth}" height="${t.cssHeight}" patternUnits="userSpaceOnUse"${tf}><use href="#${p}-tex-${name}-img"/></pattern>`
    })
  }
  return s
}

export function inkDefsSvg(o: MaskDefsOptions & { paper?: boolean } = {}): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="0" height="0" style="position:absolute" aria-hidden="true" focusable="false"><defs>${svgMaskDefs(o)}${o.paper ? svgPatternDefs({ prefix: o.prefix }) : ''}</defs></svg>`
}

export interface TextureBytes {
  png: number
  base64: number
}

export function textureBytes() {
  const of = (uri: string, png: number): TextureBytes => ({ png, base64: uri.length })
  const masks = Object.fromEntries(GRAIN_KINDS.map((k) => [k, of(GRAIN_TILES[k].uri, GRAIN_TILES[k].bytes)])) as Record<GrainMaskKind, TextureBytes>
  const paper = Object.fromEntries((Object.keys(PAPER_TILES) as PaperTileName[]).map((k) => [k, of(PAPER_TILES[k].uri, PAPER_TILES[k].bytes)])) as Record<PaperTileName, TextureBytes>
  const sum = (r: Record<string, TextureBytes>) => Object.values(r).reduce((a, b) => ({ png: a.png + b.png, base64: a.base64 + b.base64 }), { png: 0, base64: 0 })
  return { masks, paper, totals: { masks: sum(masks), paper: sum(paper) } }
}
